const APP_VERSION=3;
const Store={db:null,queue:Promise.resolve(),conflict:false,ok:true,lastError:'',folder:null,pending:0,
 async open(){try{this.db=await new Promise((res,rej)=>{const r=indexedDB.open('lifeos-vault',2);r.onupgradeneeded=()=>{for(const [n,opt] of [['snapshots',{keyPath:'id'}],['handles',undefined],['files',{keyPath:'path'}]])if(!r.result.objectStoreNames.contains(n))r.result.createObjectStore(n,opt)};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});}catch(e){this.lastError='IndexedDB недоступна; используется локальное хранилище';} },
 async latest(){if(!this.db)return null;return new Promise(res=>{const tx=this.db.transaction('snapshots');const r=tx.objectStore('snapshots').getAll();r.onsuccess=()=>res((r.result||[]).sort((a,b)=>b.id-a.id)[0]?.data||null);r.onerror=()=>res(null)})},
 async mirror(data){if(!this.db)return false;return new Promise((res,rej)=>{const tx=this.db.transaction(['snapshots','files'],'readwrite'),st=tx.objectStore('snapshots');st.put({id:data._savedAt||Date.now(),data});const fs=tx.objectStore('files');fs.clear();for(const [d,content]of Object.entries(data.entries))fs.put({path:'diary/'+d+'.md',content});const {entries,...rest}=data;fs.put({path:'data/state.yaml',content:jsyaml.dump(rest,{noRefs:true})});const r=st.getAllKeys();r.onsuccess=()=>r.result.slice(0,-12).forEach(k=>st.delete(k));tx.oncomplete=()=>res(true);tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||Error('Запись отменена'))})},
 status(){document.querySelectorAll('.save-state').forEach(e=>{e.innerHTML=ic(this.conflict||!this.ok||this.formError?'warning':this.pending?'clock':'shield-check')+`<span>${this.conflict?'Изменения в другой вкладке':this.formError?'Проверьте поля':!this.ok?'Не сохранено':this.pending?'Сохранение…':'Сохранено на устройстве'}</span>`;e.style.color=this.conflict||!this.ok||this.formError?'var(--r)':''})},
 async recover(){if(!this.db)return toast('Резервные копии недоступны');const copies=await new Promise(res=>{const r=this.db.transaction('snapshots').objectStore('snapshots').getAll();r.onsuccess=()=>res(r.result.sort((a,b)=>b.id-a.id));r.onerror=()=>res([])});modal('Локальные резервные копии',`<p class="help">До 12 последних снимков. Перед восстановлением экспортируйте текущие данные.</p>${copies.map((c,i)=>`<div class="it"><span class="sp">${esc(new Date(c.id).toLocaleString('ru-RU'))}</span><button data-a="restoreCopy" data-x="${i}">Восстановить</button></div>`).join('')||'<p>Копий пока нет.</p>'}`,()=>{},'','Готово');Store.copies=copies}
};
function normalise(raw){if(!raw||typeof raw!=='object'||Array.isArray(raw))throw Error('Некорректное состояние');const d=def(),s={...d,...raw};for(const k of ['fields','tpls','items','ledger','log','skip','cats','offCats','skills'])if(!Array.isArray(s[k]))throw Error('Ожидался список: '+k);if(!s.entries||typeof s.entries!=='object'||Array.isArray(s.entries))throw Error('Некорректный дневник');for(const [date,text] of Object.entries(s.entries)){if(!validDate(date)||typeof text!=='string')throw Error('Некорректная запись '+date);parseMd(text)}s.rules={task:{...d.rules.task,...raw.rules?.task},habit:{...d.rules.habit,...raw.rules?.habit},skill:{...d.rules.skill,...raw.rules?.skill}};s.blocks={week:[],dow:{},ex:{},...raw.blocks};if(!Array.isArray(s.blocks.week))throw Error('Неверное расписание');for(const list of [s.blocks.week,...Object.values(s.blocks.dow),...Object.values(s.blocks.ex)]){if(!Array.isArray(list))throw Error('Неверные блоки');for(const b of list){if(!Number.isFinite(b.s)||!Number.isFinite(b.e)||b.s<0||b.s>=1440||b.e<0||b.e>=1440||typeof b.name!=='string')throw Error('Неверный блок времени');b.color=safeColor(b.color)}}s.skills.forEach(n=>{if(!/^[a-zA-Z0-9_-]+$/.test(n.id||'')||typeof n.name!=='string'||!Array.isArray(n.crit))throw Error('Неверный навык');n.ok=(n.ok||[]).filter(x=>Number.isInteger(x)&&x>=0&&x<n.crit.length);n.hist=n.hist||[];n.agg=n.agg||'manual';n.crit.forEach((c,i)=>{if(!Number.isFinite(+c.v)||typeof c.t!=='string')throw Error('Неверный критерий');c.v=+c.v;c.label=c.label||String(c.v);c.id=c.id||'legacy-'+i});n.proofs=n.proofs||{};n.color=safeColor(n.color||'#567144');if(!['plant','book-open','lightning','target','tree-structure','check-square','sun'].includes(n.icon))n.icon='plant';if(n.pos&&(!Number.isFinite(n.pos.x)||!Number.isFinite(n.pos.y)))delete n.pos});let ids=new Set(s.skills.map(n=>n.id));if(ids.size!==s.skills.length)throw Error('Повтор ID навыка');s.skills.forEach(n=>{const seen=new Set([n.id]);let p=n.p;if(p&&!ids.has(p))n.p=null;while(p&&ids.has(p)){if(seen.has(p))throw Error('Цикл в дереве навыков');seen.add(p);p=s.skills.find(x=>x.id===p)?.p}});s.items.forEach(i=>{if(!/^[a-zA-Z0-9_-]+$/.test(i.id||'')||typeof i.title!=='string'||!['task','habit'].includes(i.kind))throw Error('Неверная задача');i.created=i.created||today();if(!validDate(i.created)||i.due&&!validDate(i.due))throw Error('Неверная дата задачи');i.done=i.done||{};i.rep=i.rep||{t:'none',n:1};i.exceptions=i.exceptions||[];i.seen=i.seen||{}});s.fields.forEach(f=>{if(!/^[\p{L}\p{N}_-]+$/u.test(f.id||'')||['date','_fields','__proto__','constructor','prototype'].includes(f.id)||typeof f.name!=='string')throw Error('Неверное определение поля')});s.tpls.forEach(t=>{if(typeof t.n!=='string'||!Array.isArray(t.f))throw Error('Неверный шаблон')});s.ledger.forEach(l=>{if(!/^[a-zA-Z0-9_-]+$/.test(l.id||'')||!Number.isFinite(l.amt)||!validDate(l.date))throw Error('Некорректная операция')});if(new Set(s.items.map(i=>i.id)).size!==s.items.length)throw Error('Повтор ID задачи');if(new Set(s.fields.map(f=>f.id)).size!==s.fields.length)throw Error('Повтор ключа поля');s.version=APP_VERSION;s.settings={theme:'system',weekStarts:1,...s.settings};return s}
function validDate(d){return typeof d==='string'&&/^\d{4}-\d\d-\d\d$/.test(d)&&ymd(pd(d))===d}
function safeColor(c){return /^#[0-9a-f]{6}$/i.test(c||'')?c:'#567144'}
async function boot(){await Store.open();let raw;try{raw=localStorage.getItem(KEY);const local=raw?JSON.parse(raw):null,backup=await Store.latest();S=normalise(backup&&(backup._savedAt||0)>(local?._savedAt||0)?backup:local||backup||def())}catch(e){const b=await Store.latest();try{if(b){S=normalise(b);toast('Восстановлена резервная копия. Проверьте данные.')}else{S=normalise(def());Store.ok=false;Store.lastError='Не удалось прочитать данные. Исходное хранилище не перезаписано. Импортируйте копию.';Store.blocked=true}}catch{S=normalise(def());Store.blocked=true;Store.ok=false}}document.documentElement.dataset.theme=S.settings.theme;scan();render();Store.status();if(Store.lastError)toast(Store.lastError)}
function save(){if(Store.conflict||Store.blocked){Store.ok=false;Store.status();toast(Store.conflict?'В другой вкладке изменены данные. Экспортируйте эту версию и перезагрузите страницу.':'Хранилище заблокировано после ошибки. Экспортируйте данные и восстановите копию.');return false}S._savedAt=Math.max(Date.now(),(S._savedAt||0)+1);const data=cl(S);let localOK=false;try{localStorage.setItem(KEY,JSON.stringify(data));localOK=true}catch(e){Store.lastError=e.message}Store.pending++;Store.status();Store.queue=Store.queue.then(async()=>{let mirrorOK=false;try{mirrorOK=await Store.mirror(data)}catch(e){Store.lastError=e.message}Store.ok=localOK||mirrorOK;Store.pending--;Store.status();if(!Store.ok)toast('Данные не сохранены! Освободите место и экспортируйте резервную копию.');});return localOK||!!Store.db}
window.addEventListener('beforeunload',e=>{if(typeof Diary!=='undefined'&&Diary.timer){clearTimeout(Diary.timer);Diary.timer=null;try{saveE(1)}catch{Store.formError=true}}if(Store.pending||!Store.ok||Store.formError){e.preventDefault();e.returnValue=''}});
function parseMd(text){text=(text||'').replace(/^\uFEFF/,'').replace(/\r\n/g,'\n');const m=/^---\s*\n([\s\S]*?)\n---\s*(?:\n|$)([\s\S]*)$/.exec(text);if(!m)return{fm:{},body:text};const fm=jsyaml.load(m[1],{schema:jsyaml.JSON_SCHEMA})||{};if(typeof fm!=='object'||Array.isArray(fm))throw Error('Frontmatter должен быть объектом YAML');if(Object.keys(fm).some(k=>['__proto__','constructor','prototype'].includes(k)))throw Error('Недопустимый ключ YAML');return{fm,body:m[2]}}
// dumpMd uses JSON scalar syntax, a valid subset of YAML; parser supports real nested YAML.
const Rules={for(i){const r={...S.rules[i.kind],...(i.customRules||{})};if(i.noRw||S.offCats.includes(i.cat)||i.rewardEnabled===false){r.on=0;r.late=0}if(i.noRw||S.offCats.includes(i.cat)||i.penaltyEnabled===false){r.miss=0;r.move=0}return r},isExcept(i,d){return(i.exceptions||[]).includes(d)},deleteRef(ref){S.ledger=S.ledger.filter(l=>l.ref!==ref)}};
function award(i,type,date,ref){const r=Rules.for(i);if(i.noRw||S.offCats.includes(i.cat)||(['on','late'].includes(type)&&i.rewardEnabled===false)||(['miss','move'].includes(type)&&i.penaltyEnabled===false)||!r.en||Rules.isExcept(i,date)||S.skip.includes(ref)||S.ledger.some(l=>l.ref===ref))return;const v=type==='on'&&i.rw!==''&&i.rw!=null?+i.rw:+r[type];if(!Number.isFinite(v)||!v)return;S.ledger.push({id:uid(),date,amt:v,why:i.title,cat:i.cat||'',k:type,ref});}
const Schedules={isDue(i,d){if(d<i.created||i.until&&d>i.until||Rules.isExcept(i,d))return false;const day=pd(d),days=i.days||[];if(days.length&&!days.includes(day.getDay()))return false;const n=Math.max(1,+i.every||1),unit=i.unit||'day';if(unit==='month'){const a=pd(i.created),diff=(day.getFullYear()-a.getFullYear())*12+day.getMonth()-a.getMonth();return diff%n===0&&day.getDate()===Math.min(a.getDate(),new Date(day.getFullYear(),day.getMonth()+1,0).getDate())}const delta=Math.round((Date.UTC(day.getFullYear(),day.getMonth(),day.getDate())-Date.UTC(...i.created.split('-').map((x,k)=>+x-(k===1?1:0))))/86400000);return unit==='week'?Math.floor(delta/7)%n===0:delta%n===0},next(i,d){const n=Math.max(1,+i.rep.n||1);if(i.rep.t==='month'){const dt=pd(d),orig=dt.getDate();dt.setDate(1);dt.setMonth(dt.getMonth()+n);dt.setDate(Math.min(orig,new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate()));return ymd(dt)}return addD(d,i.rep.t==='week'?7*n:n)}};
function scan(){const t=today();let changed=false;S.items.forEach(i=>{i.seen=i.seen||{};const r=Rules.for(i),gr=Math.max(0,+r.grace||0);if(i.kind==='habit'){for(let d=i.scanFrom||i.created;d<addD(t,-gr);d=addD(d,1)){if(Schedules.isDue(i,d)&&!i.done[d]&&!i.seen[d]){award(i,'miss',d,i.id+':'+d+':miss');i.seen[d]=true;changed=true}i.scanFrom=addD(d,1)}}else if(!i.fin&&i.due&&!i.missed&&t>addD(i.due,gr)&&!Rules.isExcept(i,i.due)){i.missed=1;award(i,'miss',i.due,i.id+':'+i.due+':miss');changed=true}});if(changed)save()}

function modal(title,body,ok,extra,lab){closeDD();const previous=document.activeElement;const o=document.createElement('div');o.className='ov';o.innerHTML=`<section class="md" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="mh"><h3>${esc(title)}</h3><button class="gh ib" id="mx" aria-label="Закрыть">${ic('x')}</button></div><div class="mb">${body}<div class="form-error" hidden role="alert"></div></div><div class="mf">${extra||''}<span class="sp"></span>${lab?'':'<button id="mno" class="gh">Отмена</button>'}<button class="pri" id="mok">${lab||'Сохранить'}</button></div></section>`;g('lifeos-shell').appendChild(o);deltaControls();const close=()=>{o.remove();previous?.isConnected&&previous.focus()};o.close=close;o.querySelector('#mx').onclick=close;o.querySelector('#mno')?.addEventListener('click',close);o.querySelector('#mok').onclick=async()=>{const b=o.querySelector('#mok');b.disabled=true;try{const result=await ok(o);if(result!==false)close()}catch(e){const er=o.querySelector('.form-error');er.hidden=false;er.textContent=e.message;er.scrollIntoView({block:'nearest'})}finally{b.disabled=false}};o.addEventListener('keydown',e=>{if(e.key==='Tab'){const focus=[...o.querySelectorAll('button,input:not([type=hidden]),select,textarea,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);if(e.shiftKey&&document.activeElement===focus[0]){e.preventDefault();focus.at(-1)?.focus()}else if(!e.shiftKey&&document.activeElement===focus.at(-1)){e.preventDefault();focus[0]?.focus()}}});o.querySelectorAll('.fr').forEach(fr=>{const lab=fr.querySelector('label'),input=fr.querySelector('input,select,textarea');if(lab&&input?.id)lab.htmlFor=input.id});setTimeout(()=>o.querySelector('input:not([type=checkbox]):not([type=hidden]),textarea,select,button')?.focus(),20);return o}
