const Diary={timer:null,preview:false,applying:false,words(text){return text.trim()?text.trim().split(/\s+/).length:0},templates(d){return S.tpls.filter(t=>t.when==='daily'||t.when==='dow'&&(t.days||[]).includes(pd(d).getDay())||t.when==='dates'&&(t.dates||[]).includes(d))},fieldIds(){const fm=parseMd(S.entries[D]).fm;return new Set([...(fm._fields||[]),...extra,...this.templates(D).flatMap(t=>t.f||[])])},saveSoon(){if(view!=='diary')return;clearTimeout(this.timer);Store.status();this.timer=setTimeout(()=>{this.timer=null;try{saveE(1);Store.formError=false}catch(e){Store.formError=true;toast(e.message+' — исправьте поле, чтобы сохранить запись.')}Store.status()},500)}};
