function shownFields(){const fm=parseMd(S.entries[D]).fm,ids=Diary.fieldIds(),wd=pd(D).getDay();return S.fields.filter(f=>f.when==='daily'||(f.when||'').startsWith('dow:')&&f.when.slice(4).split(',').includes(String(wd))||ids.has(f.id)||Object.hasOwn(fm,f.id))}
function saveE(quiet){if(!g('body')||Diary.preview)return;clearTimeout(Diary.timer);Diary.timer=null;const old=parseMd(S.entries[D]),fields=shownFields(),fm={...old.fm,date:D,_fields:[...new Set([...Diary.fieldIds(),...fields.map(f=>f.id)])]};for(const f of fields)fm[f.id]=rd(f);Store.formError=false;const body=g('body').value;const text=dumpMd(fm,body);if(S.entries[D]===text){if(!quiet)toast('Запись сохранена');return}S.entries[D]=text;if(!quiet)lg('Сохранена запись '+D);save();if(Store.folder)Vault.writeEntry(D,text).catch(e=>toast('Папка: '+e.message));const counter=g('word-count');if(counter)counter.textContent=Diary.words(body)+' слов';if(!quiet)toast(Store.ok?'Запись сохранена':'Проверьте сохранение данных')}
function mdPreview(s){let html=esc(s);const chunks=html.split(/```[^\n]*\n([\s\S]*?)```/g);return chunks.map((c,i)=>i%2?`<pre><code>${c}</code></pre>`:c.split('\n').map(l=>{if(/^### /.test(l))return'<h3>'+l.slice(4)+'</h3>';if(/^## /.test(l))return'<h2>'+l.slice(3)+'</h2>';if(/^# /.test(l))return'<h1>'+l.slice(2)+'</h1>';if(/^&gt; /.test(l))return'<blockquote>'+l.slice(5)+'</blockquote>';let t=l.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/`(.+?)`/g,'<code>$1</code>').replace(/\*(.+?)\*/g,'<em>$1</em>');if(/^- \[x\] /i.test(l))return'<p>☑ '+t.slice(6)+'</p>';if(/^- \[ \] /.test(l))return'<p>☐ '+t.slice(6)+'</p>';if(/^- /.test(l))return'<p>• '+t.slice(2)+'</p>';return t?'<p>'+t+'</p>':'<br>'}).join('')).join('')}
V.diary=()=>{const{fm,body}=parseMd(S.entries[D]),fields=shownFields(),date=pd(D),wd=date.toLocaleDateString('ru-RU',{weekday:'long'}),month=date.toLocaleDateString('ru-RU',{month:'long'});return pageHead('Дневник','Замечайте важное. Остальное — в вашем ритме.',`<button data-a="fieldsM">${ic('cfg')} Поля и шаблоны</button>`,'ДНЕВНИК')+`<div class="two-col"><section class="sheet"><div class="hd"><div class="date-nav"><button class="gh ib" data-a="dd" data-x="-1" aria-label="Предыдущий день">${ic('l')}</button><input aria-label="Дата записи" type="date" data-c="date" value="${D}"><button class="gh ib" data-a="dd" data-x="1" aria-label="Следующий день">${ic('r')}</button></div><span class="pill">${D===today()?'Сегодня':esc(wd)}</span></div>${fields.length?`<div class="fl">${fields.map(f=>`<div class="fr"><label for="f_${esc(f.id)}">${esc(f.name)}</label>${inp(f,fm[f.id])}</div>`).join('')}</div><div class="row"><button class="gh sm" data-a="fieldsM">${ic('plus')} Добавить поле</button></div>`:`<div class="empty-fields"><div class="empty-icon">${ic('sliders-horizontal')}</div><h3>Поля записи</h3><div class="preset-row">${PRE.map((p,k)=>`<button data-a="preset" data-x="${k}">${ic(['moon','sun','plant'][k])}${esc(p.name)}</button>`).join('')}</div><button class="gh custom-field" data-a="newF">${ic('plus')} Своё поле</button></div>`}<div class="row"><span class="section-tag" style="margin:0">Заметка дня</span><span class="sp"></span><button class="gh sm" data-a="preview">${ic(Diary.preview?'pencil-simple':'book-open')}${Diary.preview?'Редактировать':'Просмотр'}</button></div>${Diary.preview?`<div class="preview-markdown">${mdPreview(body)||'<span class="m">Заметка пока пустая.</span>'}</div>`:`<textarea class="diary-body" id="body" aria-label="Заметка дня в Markdown" placeholder="Запись в Markdown">${esc(body)}</textarea>`}<div class="entry-footer"><span class="m sm"><span id="word-count">${Diary.words(body)} слов</span> · Markdown · автосохранение</span><button class="gh sm" data-a="dlE">${ic('dl')} Скачать .md</button></div></section><aside class="stack diary-aside"><section class="card"><div class="section-tag">Ваш день</div><div class="date-block"><div class="date-square"><strong>${date.getDate()}</strong><span>${esc(month)}</span></div><div><b style="text-transform:capitalize">${esc(wd)}</b><div class="m sm">${date.getFullYear()} год</div></div></div><div style="margin-top:24px"><div class="mini-line">${ic('check')}<span>${S.items.filter(i=>i.kind==='task'&&i.due===D&&!i.fin).length} задач на этот день</span></div><div class="mini-line">${ic('repeat')}<span>${items('habit').filter(i=>Schedules.isDue(i,D)).length} привычек в расписании</span></div><div class="mini-line">${ic('diamond')}<span>${dm(+bal(S.ledger.filter(l=>l.date===D)).toFixed(2))} алмазов за день</span></div></div><button class="gh" style="padding-left:0" data-a="goPlan">К плану дня ${ic('arrow-up-right')}</button></section><button class="gh sm" data-a="exp">${ic('archive')} Резервная копия хранилища</button></aside></div>`};
