const FieldTypes={...TY,longtext:'Длинный текст',url:'Ссылка',time:'Время',json:'JSON / произвольная структура'};const oldInp=inp,oldRd=rd;
inp=function(f,v){if(f.type==='longtext')return`<textarea id="f_${esc(f.id)}" rows="3">${esc(v)}</textarea>`;if(['url','time'].includes(f.type))return`<input id="f_${esc(f.id)}" type="${f.type}" value="${esc(v)}">`;if(f.type==='json')return`<textarea id="f_${esc(f.id)}" rows="3" placeholder="{}">${esc(v==null?'':typeof v==='string'?v:JSON.stringify(v,null,2))}</textarea>`;if(f.type==='rating'){const max=Math.max(1,Math.min(100,+f.max||5));if(max>10)return`<input aria-label="${esc(f.name)} (0–${max})" id="f_${esc(f.id)}" type="number" min="0" max="${max}" step="any" value="${esc(v)}">`}return oldInp(f,v)};
rd=function(f){const v=g('f_'+f.id)?.value;if(f.type==='json'){if(!v?.trim())return null;try{return JSON.parse(v)}catch{throw Error('Поле «'+f.name+'»: некорректный JSON')}}return oldRd(f)};
function fieldM(id){saveE(1);document.querySelectorAll('.ov').forEach(x=>x.remove());const f=id?S.fields.find(x=>x.id===id):{name:'',type:'text',when:'daily',opts:[],max:5},days=f.when?.startsWith('dow:')?f.when.slice(4).split(','):[];const o=modal(id?'Настроить поле':'Своё поле',`<div class="fr"><label>Название поля</label><input id="m_n" value="${esc(f.name)}" placeholder="Например, сколько спал"></div><div class="fr"><label>Тип данных</label><select id="m_t">${Object.entries(FieldTypes).map(([k,v])=>`<option value="${k}" ${k===f.type?'selected':''}>${v}</option>`).join('')}</select></div><div class="fr"><label>Ключ в YAML</label><input id="m_key" value="${esc(f.id||'')}" placeholder="Автоматически, если оставить пустым" ${id?'readonly':''}></div><p class="help">Ключ сохраняется в Markdown и используется в статистике. После создания не меняется.</p><div class="fr"><label>Варианты выбора (по одному на строку)</label><textarea rows="3" id="m_opts">${esc((f.opts||[]).join('\n'))}</textarea></div><div class="fr"><label>Верхняя граница оценки</label><input type="number" id="m_max" min="1" max="100" value="${f.max||5}"></div><div class="fr"><label>Когда показывать</label><select id="m_w"><option value="daily" ${f.when==='daily'?'selected':''}>Каждый день</option><option value="dow" ${days.length?'selected':''}>В выбранные дни недели</option><option value="manual" ${f.when==='manual'?'selected':''}>Только в назначенных записях</option></select></div><div class="chips" id="m_days">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" value="${d}" ${days.includes(String(d))?'checked':''}>${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][d]}</label>`).join('')}</div><p class="help">Новое поле добавится в текущую запись. При удалении поля значения в Markdown останутся.</p>`,()=>{const n=g('m_n').value.trim(),type=g('m_t').value,key=id||g('m_key').value.trim()||uid(),when=g('m_w').value,ds=[...g('m_days').querySelectorAll('input:checked')].map(x=>x.value),opts=g('m_opts').value.split('\n').map(s=>s.trim()).filter(Boolean),max=+g('m_max').value;if(!n)throw Error('Введите название');if(!/^[\p{L}\p{N}_-]+$/u.test(key)||['date','_fields','__proto__','constructor','prototype'].includes(key))throw Error('Ключ: буквы, цифры, дефис и _. Служебные имена недоступны.');if(!id&&S.fields.some(x=>x.id===key))throw Error('Такой ключ уже есть');if(['select','multi'].includes(type)&&!opts.length)throw Error('Добавьте варианты выбора');if(type==='rating'&&(!Number.isInteger(max)||max<1||max>100))throw Error('Граница оценки: целое число 1–100');if(when==='dow'&&!ds.length)throw Error('Выберите дни недели');const nf={...f,id:key,name:n,type,when:when==='dow'?'dow:'+ds.join(','):when,opts,max};if(id)S.fields[S.fields.indexOf(f)]=nf;else S.fields.push(nf);extra.push(key);save();Diary.preview=false;render();saveE(1)},id?`<button class="dg" id="m_x">${ic('trash')} Удалить</button>`:'');o.querySelector('#m_x')?.addEventListener('click',()=>{if(confirm('Удалить определение поля? Значения в записях сохранятся.')){S.fields=S.fields.filter(x=>x.id!==id);save();o.close();render()}})}
function fieldsM(){saveE(1);document.querySelectorAll('.ov').forEach(x=>x.remove());const shown=shownFields();modal('Поля и шаблоны',`<div class="section-tag" style="margin-top:16px">Поля дневника</div>${S.fields.map(f=>`<div class="it"><div class="sp"><b>${esc(f.name)}</b><p class="m sm">${FieldTypes[f.type]||esc(f.type)} · ${f.when==='daily'?'ежедневно':f.when==='manual'?'по назначению':'по дням недели'}</p></div>${!shown.includes(f)?`<button data-a="addToE" data-x="${esc(f.id)}" title="Добавить в эту запись">${ic('plus')}</button>`:''}<button class="gh ib" data-a="editF" data-x="${esc(f.id)}" aria-label="Изменить поле">${ic('edit')}</button></div>`).join('')||'<p class="m sm">Создайте свои поля или выберите подсказку в дневнике.</p>'}<div class="row"><button data-a="newF">${ic('plus')} Своё поле</button></div><div class="section-tag" style="margin-top:28px">Шаблоны записей</div>${S.tpls.map((t,i)=>`<div class="it"><div class="sp"><b>${esc(t.n)}</b><p class="m sm">${t.f.length} полей · ${{daily:'каждый день',dow:'по дням недели',dates:'по датам',manual:'вручную'}[t.when||'manual']}</p></div><button class="gh" data-a="applyT" data-x="${i}">Применить</button><button class="gh ib" data-a="editT" data-x="${i}" aria-label="Изменить шаблон">${ic('edit')}</button></div>`).join('')||'<p class="m sm">Набор полей и текст для ежедневных, еженедельных или разовых записей.</p>'}<button data-a="newT">${ic('plus')} Шаблон</button>`,()=>{},'','Готово')}
function templateM(index){saveE(1);document.querySelectorAll('.ov').forEach(x=>x.remove());const t=index==null?{n:'',f:shownFields().map(f=>f.id),body:'',when:'manual',days:[],dates:[]}:S.tpls[index];const o=modal('Шаблон записи',`<div class="fr"><label>Название</label><input id="mt_n" value="${esc(t.n)}"></div><div class="fr"><label>Поля</label><div class="chips" id="mt_f">${S.fields.map(f=>`<label><input type="checkbox" value="${esc(f.id)}" ${t.f.includes(f.id)?'checked':''}>${esc(f.name)}</label>`).join('')||'<p class="help">Сначала создайте поля дневника.</p>'}</div></div><div class="fr"><label>Текст Markdown</label><textarea id="mt_body" rows="5">${esc(t.body||'')}</textarea></div><div class="fr"><label>Назначение</label><select id="mt_w">${[['manual','Только вручную'],['daily','Каждый день'],['dow','Дни недели'],['dates','Конкретные даты']].map(([v,n])=>`<option value="${v}" ${v===(t.when||'manual')?'selected':''}>${n}</option>`).join('')}</select></div><div class="chips" id="mt_days">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" value="${d}" ${(t.days||[]).includes(d)?'checked':''}>${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][d]}</label>`).join('')}</div><div class="fr"><label>Даты через запятую (ГГГГ-ММ-ДД)</label><input id="mt_dates" value="${esc((t.dates||[]).join(', '))}"></div><p class="help">Поля применяются автоматически. Текст автоматически подставляется только в новую пустую заметку; существующий текст не заменяется.</p>`,()=>{const n=g('mt_n').value.trim(),when=g('mt_w').value,days=[...g('mt_days').querySelectorAll('input:checked')].map(x=>+x.value),dates=g('mt_dates').value.split(',').map(x=>x.trim()).filter(Boolean);if(!n)throw Error('Введите название');if(when==='dow'&&!days.length)throw Error('Выберите дни недели');if(dates.some(d=>!validDate(d)))throw Error('Проверьте формат дат');if(when==='dates'&&!dates.length)throw Error('Укажите даты');const nt={...t,n,when,days,dates,f:[...g('mt_f').querySelectorAll('input:checked')].map(x=>x.value),body:g('mt_body').value};if(index==null)S.tpls.push(nt);else S.tpls[index]=nt;save();render()},index!=null?'<button class="dg" id="mt_del">Удалить</button>':'');o.querySelector('#mt_del')?.addEventListener('click',()=>{if(confirm('Удалить шаблон? Записи сохранятся.')){S.tpls.splice(index,1);save();o.close();render()}})}
A.newT=()=>templateM();A.editT=x=>templateM(+x);A.applyT=i=>{saveE(1);const t=S.tpls[+i];extra.push(...t.f);const e=parseMd(S.entries[D]);if(t.body)e.body=e.body?e.body+'\n\n'+t.body:t.body;e.fm._fields=[...new Set([...(e.fm._fields||[]),...extra])];e.fm.date=D;S.entries[D]=dumpMd(e.fm,e.body);save();document.querySelectorAll('.ov').forEach(x=>x.remove());Diary.preview=false;render();toast('Шаблон добавлен в запись')};
const diaryView=V.diary;V.diary=()=>{const e=parseMd(S.entries[D]);if(!Object.hasOwn(S.entries,D)){const ts=Diary.templates(D);if(ts.some(t=>t.body)){S.entries[D]=dumpMd({...e.fm,date:D,_fields:[...new Set([...(e.fm._fields||[]),...ts.flatMap(t=>t.f)])]},ts.map(t=>t.body||'').filter(Boolean).join('\n\n'));save()}}return diaryView()};

