function itemM(kind,id){const i=id?S.items.find(x=>x.id===id):{id:uid(),kind,title:'',cat:'',prio:2,due:'',rep:{t:'none',n:1},days:[],done:{},created:today(),rw:'',noRw:0,every:1,unit:'day',exceptions:[]},r=i.customRules||{},o=modal(id?'Настройки '+(kind==='habit'?'привычки':'задачи'):'Новая '+(kind==='habit'?'привычка':'задача'),`<div class="fr"><label>Название</label><input id="m_t" value="${esc(i.title)}" placeholder="Какой результат хотите получить?"></div><div class="fr"><label>Описание</label><textarea id="m_desc" rows="2">${esc(i.desc||'')}</textarea></div><div class="fr"><label>Категория</label>${catPick('m_c',i.cat)}</div><div class="fr"><label>Приоритет</label><select id="m_p">${[1,2,3].map(n=>`<option value="${n}" ${n===i.prio?'selected':''}>${['','Низкий','Обычный','Высокий'][n]}</option>`).join('')}</select></div>${kind==='task'?`<div class="fr"><label>Срок выполнения</label><input id="m_d" type="date" value="${i.due||''}"></div><div class="fr"><label>Повторять</label><input id="m_rn" type="number" min="1" max="10000" value="${i.rep.n||1}" aria-label="Интервал повторения"><select id="m_rt">${[['none','Не повторять'],['day','Дней'],['week','Недель'],['month','Месяцев']].map(([k,v])=>`<option value="${k}" ${k===i.rep.t?'selected':''}>${v}</option>`).join('')}</select></div><p class="help">Повтор создаётся после выполнения, от предыдущего срока. В коротком месяце выбирается последний день.</p>`:`<div class="fr"><label>Начало / окончание (необязательно)</label><input id="m_start" type="date" value="${i.created}"><input id="m_until" type="date" value="${i.until||''}"></div><div class="fr"><label>Каждые</label><input id="m_every" type="number" min="1" value="${i.every||1}"><select id="m_unit">${[['day','Дней'],['week','Недель'],['month','Месяцев']].map(([v,n])=>`<option value="${v}" ${v===(i.unit||'day')?'selected':''}>${n}</option>`).join('')}</select></div><div class="fr"><label>Дни недели (пусто — любой)</label><div class="chips" id="m_dy">${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" value="${d}" ${(i.days||[]).includes(d)?'checked':''}>${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][d]}</label>`).join('')}</div></div><p class="help">Интервал считается от даты начала; дни недели — дополнительный фильтр. Для еженедельного расписания выберите недели и нужные дни.</p>`}<details><summary>Награды, штрафы и исключения</summary><div class="fr"><label>Награда в срок (пусто — из общих правил)</label><input id="m_rw" type="number" step="any" value="${esc(i.rw??'')}"></div><div class="grid">${[['late','С опозданием'],['miss','Пропуск'],['move','Перенос'],['grace','Отсрочка, дней']].map(([k,n])=>`<label>${n}<input id="m_rule_${k}" type="number" step="${k==='grace'?'1':'any'}" ${k==='grace'?'min="0"':''} value="${esc(r[k]??'')}" placeholder="Из общих правил"></label>`).join('')}</div><div class="row"><label><input id="m_reward_on" type="checkbox" ${i.rewardEnabled!==false&&!i.noRw?'checked':''}> Награды</label><label><input id="m_penalty_on" type="checkbox" ${i.penaltyEnabled!==false&&!i.noRw?'checked':''}> Штрафы</label></div><div class="fr"><label>Исключения — даты через запятую</label><input id="m_except" value="${esc((i.exceptions||[]).join(', '))}" placeholder="2026-12-31, 2027-01-01"></div><p class="help">В даты исключений событие не обязательно и не влияет на баланс. Уже начисленные операции меняются только вручную в наградах. Суммы штрафов указываются со знаком минус.</p></details>`,()=>{const title=g('m_t').value.trim(),ex=g('m_except').value.split(',').map(x=>x.trim()).filter(Boolean);if(!title)throw Error('Введите название');if(ex.some(d=>!validDate(d)))throw Error('Проверьте даты исключений');const newDue=kind==='task'?g('m_d').value:'';if(kind==='task'&&g('m_rt').value!=='none'&&!newDue)throw Error('Для повторения нужен срок');const cr={};for(const k of ['late','miss','move','grace']){const v=g('m_rule_'+k).value;if(v!==''){if(!Number.isFinite(+v))throw Error('Некорректное правило');if(k==='grace'&&(!Number.isInteger(+v)||+v<0))throw Error('Отсрочка — целое число дней от 0');cr[k]=+v}}if(kind==='habit'&&(!g('m_start').value||!Number.isInteger(+g('m_every').value)||+g('m_every').value<1))throw Error('Укажите начало и целый интервал от 1');if(kind==='habit'&&g('m_until').value&&g('m_until').value<g('m_start').value)throw Error('Окончание раньше начала');if(kind==='task'&&(!Number.isInteger(+g('m_rn').value)||+g('m_rn').value<1))throw Error('Интервал — целое число от 1');const oldDue=i.due;Object.assign(i,{title,desc:g('m_desc').value,cat:g('m_c').dataset.v||'',prio:+g('m_p').value,rw:g('m_rw').value,customRules:cr,rewardEnabled:g('m_reward_on').checked,penaltyEnabled:g('m_penalty_on').checked,noRw:0,exceptions:ex});if(kind==='task'){i.due=newDue;i.rep={t:g('m_rt').value,n:+g('m_rn').value};if(id&&oldDue&&newDue!==oldDue){i.moves=(i.moves||0)+1;award(i,'move',today(),i.id+':move:'+i.moves);i.missed=0}}else{const prev=i.created;i.created=g('m_start').value;i.until=g('m_until').value;i.every=+g('m_every').value;i.unit=g('m_unit').value;i.days=[...g('m_dy').querySelectorAll('input:checked')].map(x=>+x.value);if(prev!==i.created)i.scanFrom=i.created}if(!id)S.items.push(i);lg((id?'Изменено: ':'Создано: ')+i.title);save();scan();render()});return o}
V.tasks=()=>{const list=items('task').filter(i=>(!tf||i.cat===tf)&&(!taskSearch||i.title.toLowerCase().includes(taskSearch.toLowerCase()))&&(taskStatus==='all'||taskStatus==='done'&&i.fin||taskStatus==='open'&&!i.fin)).sort((a,b)=>Number(!!a.fin)-Number(!!b.fin)||(a.due||'9999').localeCompare(b.due||'9999')||b.prio-a.prio);return pageHead('Задачи','Освободите голову для того, что действительно важно.',`<button class="pri" data-a="newI" data-x="task">${ic('plus')} Новая задача</button>`,'ДЕЙСТВИЯ')+`<div class="row"><div class="seg">${[['open','В работе'],['done','Готово'],['all','Все']].map(([v,n])=>`<button class="${taskStatus===v?'on':''}" data-a="taskStatus" data-x="${v}">${n}</button>`).join('')}</div><span class="sp"></span><input aria-label="Поиск задач" placeholder="Поиск задач" value="${esc(taskSearch)}" data-c="taskSearch"><select aria-label="Категория задач" data-c="tf"><option value="">Все категории</option>${S.cats.map(c=>`<option ${c===tf?'selected':''}>${esc(c)}</option>`).join('')}</select></div><section class="card">${list.map(i=>`<div class="it task-row ${i.fin?'done':''}"><button class="ib ${i.fin?'g':''}" data-a="done" data-x="${i.id}" aria-label="${i.fin?'Отменить выполнение':'Выполнить задачу'}">${ic(i.fin?'check-circle':'check-square')}</button><div class="sp"><div class="title">${esc(i.title)}</div><p class="m sm">${i.cat?esc(i.cat)+' · ':''}<span class="${i.due<today()&&!i.fin?'rd':''}">${i.due?esc(i.due):'Без срока'}</span> ${i.rep.t!=='none'?' · повторяется':''}${i.fin==='late'?' · выполнено позднее':''}${i.moves?' · переносов: '+i.moves:''}</p></div>${i.prio===3?'<span class="pill">Высокий</span>':''}<div class="task-actions">${!i.fin?`<button class="gh ib" data-a="mv" data-x="${i.id}" title="Перенести">${ic('mv')}</button>`:''}<button class="gh ib" data-a="editI" data-x="${i.id}" title="Редактировать">${ic('edit')}</button><button class="gh ib dg" data-a="delI" data-x="${i.id}" title="Удалить">${ic('trash')}</button></div>`).join('')||empty('check-square','Можно выдохнуть','Здесь пока нет задач для выбранного фильтра.','<button data-a="newI" data-x="task">'+ic('plus')+' Добавить задачу</button>')}</section>`};
A.taskStatus=x=>{taskStatus=x;render()};C.taskSearch=v=>{taskSearch=v;render()};
A.done=id=>{const i=S.items.find(x=>x.id===id),t=today();if(i.fin){if(i.spawned){const next=S.items.find(x=>x.id===i.spawned);if(next&&(next.fin||next.moves||next.edited))return toast('Повтор уже изменён. Сначала удалите или отмените его.');S.items=S.items.filter(x=>x.id!==i.spawned);i.spawned=null}i.fin=null;i.completedAt=null;Rules.deleteRef(id+':fin');lg('Отменено выполнение: '+i.title)}else{const late=i.due&&t>addD(i.due,Math.max(0,+Rules.for(i).grace||0));i.fin=late?'late':'on';i.completedAt=new Date().toISOString();award(i,i.fin,t,id+':fin');lg('Выполнено: '+i.title);if(i.rep.t!=='none'&&i.due&&!i.spawned){const n={...cl(i),id:uid(),fin:null,missed:0,spawned:null,moves:0,done:{},seen:{},created:t,scanFrom:t,completedAt:null,parentOccurrence:id,due:Schedules.next(i,i.due)};i.spawned=n.id;S.items.push(n)}}save();render()};
A.mv=id=>{const i=S.items.find(x=>x.id===id);modal('Перенести задачу',`<p>${esc(i.title)}</p><div class="fr"><label>Новый срок</label><input id="move_date" type="date" value="${addD(i.due||today(),1)}"></div><div class="fr"><label>Причина (необязательно)</label><input id="move_reason"></div><p class="help">Правило переноса: ${Rules.for(i).move||0} алмазов. Даты-исключения и отключение штрафов учитываются.</p>`,()=>{const d=g('move_date').value;if(!validDate(d))throw Error('Укажите дату');if(i.due===d)return;i.moves=(i.moves||0)+1;i.moveHistory=i.moveHistory||[];i.moveHistory.push({from:i.due,to:d,at:today(),reason:g('move_reason').value});award(i,'move',today(),i.id+':move:'+i.moves);i.due=d;i.missed=0;lg('Перенос: '+i.title+' → '+d);save();render()})};
V.habits=()=>{const days=[6,5,4,3,2,1,0].map(n=>addD(D,-n));return pageHead('Привычки','Не идеальная серия, а удобный вам ритм.',`<button class="pri" data-a="newI" data-x="habit">${ic('plus')} Новая привычка</button>`,'РИТМ ЖИЗНИ')+`<div class="row"><div class="date-nav"><button class="gh ib" data-a="dd" data-x="-7" aria-label="Предыдущая неделя">${ic('l')}</button><input aria-label="Последний день недели" type="date" data-c="date" value="${D}"><button class="gh ib" data-a="dd" data-x="7" aria-label="Следующая неделя">${ic('r')}</button></div>${D!==today()?'<button class="gh" data-a="dd" data-x="0">Сегодня</button>':''}</div><section class="card">${items('habit').map(i=>`<div class="it habit-row"><div class="sp"><b>${esc(i.title)}</b><p class="m sm">${esc(i.cat||'Без категории')} · каждые ${i.every||1} ${{day:'дн.',week:'нед.',month:'мес.'}[i.unit||'day']}</p></div><div class="habit-week">${days.map(d=>{const due=Schedules.isDue(i,d);return`<div><span class="week-day">${pd(d).toLocaleDateString('ru-RU',{weekday:'short'})}</span><button class="dh ${i.done[d]?'d':due?'':'n'}" data-a="hab" data-x="${i.id}|${d}" ${d>today()||!due&&!i.done[d]?'disabled':''} aria-label="${esc(i.title)}: ${d}, ${i.done[d]?'выполнено':due?'отметить':'не запланировано'}" title="${d}">${i.done[d]?ic('check'):+d.slice(8)}</button></div>`}).join('')}</div><button class="gh ib" data-a="editI" data-x="${i.id}" title="Изменить">${ic('edit')}</button><button class="gh ib dg" data-a="delI" data-x="${i.id}" title="Удалить">${ic('trash')}</button></div>`).join('')||empty('repeat','Найдите свой ритм','Любая периодичность, ваши награды и право на исключения.','<button data-a="newI" data-x="habit">'+ic('plus')+' Добавить привычку</button>')}</section><p class="help">Выберите прошлую дату, чтобы отметить выполнение задним числом. Такая отметка считается поздней после заданной отсрочки.</p>`};
A.hab=x=>{const[id,d]=x.split('|'),i=S.items.find(z=>z.id===id),t=today(),ref=id+':'+d;if(d>t||!Schedules.isDue(i,d)&&!i.done[d])return;if(i.done[d]){delete i.done[d];Rules.deleteRef(ref+':ok');delete i.seen[d];i.scanFrom=i.created;lg('Отменена отметка: '+i.title+' '+d)}else{const ty=t<=addD(d,Math.max(0,+Rules.for(i).grace||0))?'on':'late';i.done[d]=ty;Rules.deleteRef(ref+':miss');award(i,ty,d,ref+':ok');lg('Привычка: '+i.title+' '+d)}save();scan();render()};

/* Skill levels are achievements, never percentages. Canvas positions are persisted. */
const Skills={mode:'canvas',camera:{x:40,y:40,z:1},selected:null,
 level(n,seen=new Set()){if(seen.has(n.id))return null;seen.add(n.id);const cs=kids(n.id);if(cs.length&&n.agg&&n.agg!=='manual'){const nums=cs.map(c=>({v:this.level(c,new Set(seen))?.v??0,w:Math.max(0,+c.weight||1)}));const val=n.agg==='max'?Math.max(...nums.map(x=>x.v)):n.agg==='min'?Math.min(...nums.map(x=>x.v)):n.agg==='sum'?nums.reduce((a,x)=>a+x.v,0):n.agg==='weighted'?nums.reduce((a,x)=>a+x.v*x.w,0)/nums.reduce((a,x)=>a+x.w,0):nums.reduce((a,x)=>a+x.v,0)/nums.length;return[...n.crit].sort((a,b)=>b.v-a.v).find(c=>c.v<=val)||null}return n.crit.filter((c,i)=>n.ok.includes(i)).sort((a,b)=>b.v-a.v)[0]||null},
 badge(n){const l=this.level(n);return`<span class="level-badge">${ic('target')}${l?'Уровень '+esc(l.label||l.v):'Уровень не подтверждён'}</span>`},
 positions(force=false){let leaf=0;const walk=(n,depth)=>{const cs=kids(n.id);let y;if(cs.length){const ys=cs.map(c=>walk(c,depth+1));y=(ys[0]+ys.at(-1))/2}else y=(leaf++)*190+50;if(force||!n.pos)n.pos={x:40+depth*330,y};return y};kids(null).forEach(n=>{walk(n,0);leaf++})},
 canvas(){this.positions();return`<div class="canvas-wrap"><div class="canvas-toolbar"><span class="pill">${S.skills.length} узлов</span><span class="sp"></span><button class="gh ib" data-a="zoom" data-x="-1" aria-label="Уменьшить">${ic('minus')}</button><span id="zoom-label" class="sm m">${this.camera.z.toFixed(2)}×</span><button class="gh ib" data-a="zoom" data-x="1" aria-label="Увеличить">${ic('plus')}</button><button class="gh" data-a="fitCanvas" title="Показать всё">${ic('crosshair')}<span class="sm">Обзор</span></button><button class="gh ib" data-a="layoutSkills" aria-label="Упорядочить узлы">${ic('tree')}</button></div><div class="canvas-viewport" id="skill-canvas" tabindex="0" aria-label="Канвас навыков. Перетаскивайте фон для перемещения, узлы для компоновки; Enter открывает выбранный навык.">${S.skills.length?`<div class="canvas-world" id="skill-world"><svg aria-hidden="true">${S.skills.filter(n=>n.p).map(n=>{const p=S.skills.find(s=>s.id===n.p);if(!p)return'';return`<path data-edge="${n.id}" d="${this.edge(p,n)}" fill="none" stroke="var(--b)" stroke-width="2"/>`}).join('')}</svg>${S.skills.map(n=>`<div class="skill-node" role="button" tabindex="0" aria-label="Открыть навык ${esc(n.name)}" data-node="${n.id}" style="left:${n.pos.x}px;top:${n.pos.y}px"><div class="row" style="margin:0 0 12px"><span class="node-icon">${ic(n.icon||'plant')}</span><span class="sp"></span><span class="m sm">${kids(n.id).length?kids(n.id).length+' поднавыка':'навык'}</span></div><h3>${esc(n.name)}</h3>${this.badge(n)}<div class="node-bottom"><span>${n.ok.length} из ${n.crit.length} критериев</span>${ic('arrow-up-right')}</div><div class="progress-steps">${n.crit.slice(0,9).map((c,i)=>`<i class="${n.ok.includes(i)?'on':''}"></i>`).join('')}</div></div>`).join('')}</div>`:empty('tree','Ваше развитие — не шкала процентов','Создайте первый навык, определите уровни и результаты. Поднавыки появятся на канвасе.','<button class="pri" data-a="addS">'+ic('plus')+' Создать навык</button>')}</div><div class="canvas-hint">Перетаскивание · Ctrl + колесо — масштаб</div></div>`},
 edge(p,n){const x1=p.pos.x+240,y1=p.pos.y+88,x2=n.pos.x,y2=n.pos.y+88;return`M${x1} ${y1} C${x1+60} ${y1},${x2-60} ${y2},${x2} ${y2}`},
 transform(){const w=g('skill-world');if(w)w.style.transform=`translate(${this.camera.x}px,${this.camera.y}px) scale(${this.camera.z})`;if(g('zoom-label'))g('zoom-label').textContent=this.camera.z.toFixed(2)+'×'},
 bindCanvas(){if(innerWidth<=800&&!this.mobileFitted&&S.skills.length){this.mobileFitted=true;this.camera={x:24-Math.min(...S.skills.map(n=>n.pos.x))*.9,y:24-Math.min(...S.skills.map(n=>n.pos.y))*.9,z:.9}}this.transform();const c=g('skill-canvas');let drag=null;const pointers=new Map();c.onpointerdown=e=>{if(e.target.closest('button'))return;const node=e.target.closest('[data-node]'),n=node&&S.skills.find(x=>x.id===node.dataset.node);pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===2){const pts=[...pointers.values()];drag={pinch:true,dist:Math.hypot(pts[0].x-pts[1].x,pts[0].y-pts[1].y),z:this.camera.z};c.setPointerCapture(e.pointerId);return}drag={n,el:node,x:e.clientX,y:e.clientY,ox:n?n.pos.x:this.camera.x,oy:n?n.pos.y:this.camera.y,moved:false};c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!drag)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(drag.pinch&&pointers.size===2){const a=[...pointers.values()];this.camera.z=Math.max(.25,Math.min(2,drag.z*Math.hypot(a[0].x-a[1].x,a[0].y-a[1].y)/drag.dist));this.transform();return}const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)<5&&!drag.moved)return;drag.moved=true;if(drag.n){drag.n.pos={x:drag.ox+dx/this.camera.z,y:drag.oy+dy/this.camera.z};drag.el.style.left=drag.n.pos.x+'px';drag.el.style.top=drag.n.pos.y+'px';S.skills.filter(n=>n.p).forEach(n=>{const p=S.skills.find(x=>x.id===n.p),path=c.querySelector(`[data-edge="${CSS.escape(n.id)}"]`);if(p&&path)path.setAttribute('d',this.edge(p,n))})}else{this.camera.x=drag.ox+dx;this.camera.y=drag.oy+dy;this.transform()}};c.onpointerup=e=>{pointers.delete(e.pointerId);if(!drag)return;const d=drag;drag=null;pointers.clear();if(d.pinch)return;if(d.moved){if(d.n)save()}else if(d.n)this.detail(d.n.id)};c.onpointercancel=()=>{drag=null;pointers.clear()};c.onwheel=e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();this.camera.z=Math.max(.25,Math.min(2,this.camera.z*(e.deltaY>0?.9:1.1)));this.transform()};c.addEventListener('wheel',c.onwheel,{passive:false});c.onkeydown=e=>{const node=e.target.closest('[data-node]');if(node&&['Enter',' '].includes(e.key)){e.preventDefault();this.detail(node.dataset.node)}else if(!node&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();this.camera.x+=e.key==='ArrowLeft'?40:e.key==='ArrowRight'?-40:0;this.camera.y+=e.key==='ArrowUp'?40:e.key==='ArrowDown'?-40:0;this.transform()}}},
 detail(id){const n=S.skills.find(x=>x.id===id);if(!n)return;this.selected=id;document.querySelectorAll('.ov').forEach(x=>x.remove());modal(n.name,`<div style="margin:16px 0">${this.badge(n)}</div><p class="m">${esc(n.desc||'Описание не добавлено.')}</p><div class="row"><button data-a="editS" data-x="${id}">${ic('edit')} Настроить</button><button data-a="addS" data-x="${id}">${ic('plus')} Поднавык</button></div>${kids(n.id).length&&n.agg!=='manual'?`<div class="scope-note">Уровень родителя рассчитан по дочерним: ${{avg:'среднее',weighted:'взвешенное среднее',min:'минимум',max:'максимум',sum:'сумма'}[n.agg]}. Автоматический расчёт не подтверждает доказательства и не выдаёт награды.</div>`:''}<h3 style="margin-top:24px">Критерии уровней</h3>${n.crit.map((c,i)=>`<div class="criteria-row"><button data-a="crit" data-x="${id}|${i}" class="${n.ok.includes(i)?'g':''}" aria-label="${n.ok.includes(i)?'Отменить подтверждение':'Подтвердить уровень'} ${esc(c.label||c.v)}">${ic(n.ok.includes(i)?'check-circle':'check-square')}</button><div class="sp"><div class="badge">УРОВЕНЬ ${esc(c.label||c.v)}</div><div>${esc(c.t)}</div>${n.proofs[c.id]?`<div class="proof">Доказательство: ${esc(n.proofs[c.id])}</div>`:''}</div></div>`).join('')}<h3 style="margin-top:24px">История достижений</h3>${[...n.hist].reverse().map(h=>`<div class="history-row"><span class="m sm">${esc(h.d)}</span><p>${esc(h.t)}</p>${h.proof?`<p class="m sm">${esc(h.proof)}</p>`:''}</div>`).join('')||'<p class="m sm">Подтвердите результат, когда он будет достигнут.</p>'}`,()=>{},'','Готово')}
};
function skillList(p=null){return`<div class="skill-list ${p===null?'root':''}">${kids(p).map(n=>`<div class="skill-row"><span class="node-icon">${ic(n.icon||'plant')}</span><div class="sp"><div class="name">${esc(n.name)}</div><div class="row">${Skills.badge(n)}<span class="m sm">${n.ok.length} / ${n.crit.length} критериев</span></div></div><button class="gh" data-a="detailS" data-x="${n.id}">Открыть ${ic('arrow-up-right')}</button><button class="gh ib" data-a="addS" data-x="${n.id}" aria-label="Добавить поднавык">${ic('plus')}</button></div>${skillList(n.id)}`).join('')}</div>`}
V.skills=()=>pageHead('Древо навыков','Уровни, которые означают реальные достижения. Не проценты.',`<button class="pri" data-a="addS">${ic('plus')} Новый навык</button>`,'КАРТА РАЗВИТИЯ')+`<div class="hd"><div class="seg"><button class="${Skills.mode==='canvas'?'on':''}" data-a="skillMode" data-x="canvas">${ic('squares-four')} Канвас</button><button class="${Skills.mode==='list'?'on':''}" data-a="skillMode" data-x="list">${ic('list')} Дерево</button></div><span class="m sm">${S.skills.length} навыков</span></div>${Skills.mode==='canvas'?Skills.canvas():`<div class="card">${S.skills.length?skillList():empty('tree','Добавьте первый навык','У каждого узла своя шкала уровней и проверяемые критерии.')}</div>`}`;
function skillM(id,parent){document.querySelectorAll('.ov').forEach(x=>x.remove());const n=id?S.skills.find(x=>x.id===id):{id:uid(),name:'',desc:'',crit:[],ok:[],hist:[],proofs:{},agg:'manual',p:parent||null,rw:'',noRw:true,weight:1,icon:'plant'},ban=new Set([n.id]);let changed=true;while(changed){changed=false;S.skills.forEach(s=>{if(ban.has(s.p)&&!ban.has(s.id)){ban.add(s.id);changed=true}})}const o=modal(id?'Настроить навык':'Новый навык',`<div class="fr"><label>Название</label><input id="sk_name" value="${esc(n.name)}" placeholder="Например, английский язык"></div><div class="fr"><label>Описание</label><textarea id="sk_desc" rows="2">${esc(n.desc)}</textarea></div><div class="fr"><label>Иконка</label><div class="skill-icon-picker"><input id="sk_icon" type="hidden" value="${n.icon||'plant'}"><button type="button" class="skill-icon-trigger" data-a="toggleSkillIcons" aria-label="Выбрать иконку" aria-expanded="false">${ic(n.icon||'plant')}${ic('caret-down')}</button><div class="skill-icon-options" role="listbox" aria-label="Иконка навыка" hidden>${[['plant','Рост'],['book-open','Книга'],['lightning','Молния'],['target','Мишень'],['tree-structure','Дерево'],['check-square','Задача'],['sun','Солнце'],['moon','Луна'],['clock','Часы'],['notebook','Блокнот'],['calendar-blank','Календарь'],['chart-bar','Статистика']].map(([v,t])=>`<button type="button" role="option" aria-label="${t}" aria-selected="${v===n.icon}" title="${t}" data-a="chooseSkillIcon" data-x="${v}">${ic(v)}</button>`).join('')}</div></div></div><div class="fr"><label>Родительский навык</label><select id="sk_parent"><option value="">Самостоятельный навык</option>${S.skills.filter(s=>!ban.has(s.id)).map(s=>`<option value="${s.id}" ${s.id===n.p?'selected':''}>${esc(s.name)}</option>`).join('')}</select></div><div class="fr"><label>Критерии уровней — от 3 до 100</label><textarea id="sk_crit" rows="8" placeholder="1 | Представиться и поддержать короткий диалог&#10;50 | Провести рабочую встречу без переводчика&#10;100 | Выступить на конференции и ответить на вопросы">${esc(n.crit.map(c=>(c.label||c.v)+' | '+c.t).join('\n'))}</textarea></div><p class="help">Одна строка = «уровень | подтверждаемый результат». Числа могут быть любыми возрастающими значениями (1, 50, 100 или 2, 4, 8). Можно использовать названия: «Базовый», «Уверенный», «Мастер» — тогда для необязательного расчёта родителя используются порядковые номера.</p><div class="fr"><label>Расчёт уровня родителя</label><select id="sk_agg">${[['manual','Только мои подтверждённые критерии'],['avg','Среднее уровней детей'],['weighted','Взвешенное среднее'],['min','Минимальный уровень детей'],['max','Максимальный уровень детей'],['sum','Сумма уровней детей']].map(([v,t])=>`<option value="${v}" ${v===n.agg?'selected':''}>${t}</option>`).join('')}</select></div><p class="help">Расчёт необязателен. Результат сопоставляется с наибольшим не превышающим его уровнем из вашей шкалы. Для разнородных шкал оставьте ручное подтверждение.</p><div class="fr"><label>Вес этого узла для взвешенного расчёта родителя</label><input id="sk_weight" type="number" step="any" min="0.01" value="${n.weight||1}"></div><div class="row"><label><input id="sk_reward_on" type="checkbox" ${!n.noRw?'checked':''}> Награждать за ручное подтверждение уровня</label></div><div class="fr"><label>Алмазов за уровень (пусто — общие правила)</label><input id="sk_reward" type="number" step="any" value="${esc(n.rw??'')}"></div><p class="help">При изменении текста критерия его подтверждение сбрасывается; история и прошлые награды сохраняются. Снятие подтверждения вручную отменяет его награду.</p>`,()=>{const name=g('sk_name').value.trim(),lines=g('sk_crit').value.split('\n').map(x=>x.trim()).filter(Boolean);if(!name)throw Error('Введите название навыка');if(lines.length<3||lines.length>100)throw Error('Нужно от 3 до 100 критериев');const cr=lines.map((line,i)=>{const k=line.indexOf('|');if(k<1||!line.slice(k+1).trim())throw Error('Строка '+(i+1)+': укажите уровень и реальный результат через |');const label=line.slice(0,k).trim(),v=Number.isFinite(Number(label))?Number(label):i+1,t=line.slice(k+1).trim();return{label,v,t,id:n.crit.find(c=>(c.label||String(c.v))===label&&c.t===t)?.id||uid()}});if(new Set(cr.map(c=>c.label)).size!==cr.length)throw Error('Названия уровней не должны повторяться');if(cr.some((c,i)=>i&&c.v<=cr[i-1].v))throw Error('Значения уровней должны возрастать. Не смешивайте числовые и именованные шкалы.');if(!Number.isFinite(+g('sk_weight').value)||+g('sk_weight').value<=0)throw Error('Вес должен быть больше нуля');const confirmed=new Set(n.ok.map(i=>n.crit[i]?.id));Object.assign(n,{name,desc:g('sk_desc').value,icon:g('sk_icon').value,p:g('sk_parent').value||null,crit:cr,ok:cr.map((c,i)=>confirmed.has(c.id)?i:-1).filter(i=>i>=0),agg:g('sk_agg').value,weight:+g('sk_weight').value,rw:g('sk_reward').value,noRw:!g('sk_reward_on').checked});if(!id){S.skills.push(n);Skills.positions(true)}lg((id?'Изменён':'Создан')+' навык: '+name);save();render()},id?'<button class="dg" id="sk_delete">'+ic('trash')+' Удалить</button>':'');o.querySelector('#sk_delete')?.addEventListener('click',()=>{if(confirm('Удалить этот навык и все его поднавыки? История баланса сохранится.')){S.skills=S.skills.filter(s=>!ban.has(s.id));save();o.close();render()}})}
A.skillMode=x=>{Skills.mode=x;render()};A.detailS=x=>Skills.detail(x);A.zoom=x=>{Skills.camera.z=Math.max(.25,Math.min(2,Skills.camera.z*(+x>0?1.2:1/1.2)));Skills.transform()};A.fitCanvas=()=>{if(!S.skills.length)return;const w=g('skill-canvas').clientWidth,h=g('skill-canvas').clientHeight,minX=Math.min(...S.skills.map(n=>n.pos.x)),minY=Math.min(...S.skills.map(n=>n.pos.y)),maxX=Math.max(...S.skills.map(n=>n.pos.x+240)),maxY=Math.max(...S.skills.map(n=>n.pos.y+180)),z=Math.max(.15,Math.min(1,(w-40)/(maxX-minX),(h-40)/(maxY-minY)));Skills.camera={z,x:(w-(maxX-minX)*z)/2-minX*z,y:(h-(maxY-minY)*z)/2-minY*z};Skills.transform()};A.layoutSkills=()=>{Skills.positions(true);save();render();A.fitCanvas()};
A.crit=x=>{const[id,idx]=x.split('|'),n=S.skills.find(n=>n.id===id),i=+idx,c=n.crit[i],ref='sk:'+id+':'+c.id;document.querySelectorAll('.ov').forEach(o=>o.remove());if(n.ok.includes(i)){modal('Отменить подтверждение?',`<p>Уровень ${esc(c.label||c.v)}: ${esc(c.t)}</p><p class="help">Связанная награда будет отменена. Событие останется в истории.</p>`,()=>{n.ok=n.ok.filter(k=>k!==i);Rules.deleteRef(ref);Rules.deleteRef('sk:'+id+':'+i);n.hist.push({d:today(),t:'Снято подтверждение уровня '+(c.label||c.v)});delete n.proofs[c.id];lg('Отменён уровень: '+n.name);save();render();Skills.detail(id)},'','Отменить подтверждение');return}modal('Подтвердить уровень '+(c.label||c.v),`<p>${esc(c.t)}</p><div class="fr"><label>Доказательство результата</label><textarea rows="4" id="sk_proof" placeholder="Ссылка на работу, результат проверки, заметка о достижении…"></textarea></div><p class="help">Подтверждаете вы. Доказательство необязательно; автоматической внешней проверки нет.</p>`,()=>{const proof=g('sk_proof').value;n.ok.push(i);n.proofs[c.id]=proof;n.hist.push({d:today(),t:'Подтверждён уровень '+(c.label||c.v)+': '+c.t,proof});award({kind:'skill',title:n.name+' → '+(c.label||c.v),rw:n.rw,noRw:n.noRw,cat:''},'on',today(),ref);lg('Достигнут уровень: '+n.name+' '+(c.label||c.v));save();render();Skills.detail(id)},'','Подтвердить')};

A.toggleSkillIcons=()=>{const p=document.querySelector('.skill-icon-options'),b=document.querySelector('.skill-icon-trigger');p.hidden=!p.hidden;b.setAttribute('aria-expanded',String(!p.hidden))};
A.chooseSkillIcon=x=>{g('sk_icon').value=x;document.querySelector('.skill-icon-trigger').innerHTML=ic(x)+ic('caret-down');document.querySelectorAll('.skill-icon-options [role=option]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.x===x)));document.querySelector('.skill-icon-options').hidden=true;document.querySelector('.skill-icon-trigger').setAttribute('aria-expanded','false')};

/* Planner: base-day template, weekday overrides, and date-only exceptions. */
const Planner={list(){return scope==='date'?getB(D):scope==='dow'?(S.blocks.dow[pd(D).getDay()]||S.blocks.week):S.blocks.week},label(){return{date:'Только '+D,dow:'Каждый '+pd(D).toLocaleDateString('ru-RU',{weekday:'long'}),week:'Общий шаблон для всех дней'}[scope]},clock(){const B=this.list();let s=`<svg id="clk" viewBox="-16 -16 352 352" role="img" aria-label="Круговой планировщик на 24 часа"><circle cx="160" cy="160" r="139" class="ring"/><circle cx="160" cy="160" r="85" class="ring"/>`;for(let h=0;h<24;h++){const[a,b]=pt(h*60,h%3?135:130),[c,d]=pt(h*60,140),[x,y]=pt(h*60,154);s+=`<line x1="${a}" y1="${b}" x2="${c}" y2="${d}" stroke="var(--m)"/><text class="tx" x="${x}" y="${+y+4}" style="font-size:10px">${h}</text>`}B.forEach((b,i)=>{s+=`<path class="blk" data-i="${i}" d="${arc(b.s,b.e,87,137)}" fill="${safeColor(b.color)}" tabindex="0" role="button" aria-label="${esc(b.name)} ${tm(b.s)}–${tm(b.e)}"><title>${esc(b.name)} · ${tm(b.s)}–${tm(b.e)}</title></path>`});if(D===today()&&scope==='date'){const now=new Date(),[x,y]=pt(now.getHours()*60+now.getMinutes(),143);s+=`<line x1="160" y1="160" x2="${x}" y2="${y}" stroke="var(--r)" stroke-width="1.5" pointer-events="none"/><circle cx="160" cy="160" r="3" fill="var(--r)"/>`}let booked=new Set();B.forEach(b=>{for(let m=b.s;m!==b.e;m=(m+1)%1440){booked.add(m);if(booked.size>=1440)break}});s+=`<text class="tx" x="160" y="150" style="font-size:25px;fill:var(--t)">${(booked.size/60).toLocaleString('ru-RU',{maximumFractionDigits:1})} ч</text><text class="tx" x="160" y="174" style="font-size:10px">ЗАПЛАНИРОВАНО</text></svg>`;return s}};
V.plan=()=>pageHead('Планировщик','Ваши 24 часа. Планируйте день, не ограничивая себя.',`<button class="pri" data-a="newB">${ic('plus')} Блок времени</button>`,'ПЛАНИРОВЩИК')+`<div class="row planner-toolbar"><div class="date-nav"><button class="gh ib" data-a="dd" data-x="-1" aria-label="Предыдущий день">${ic('l')}</button><input type="date" data-c="date" aria-label="Дата расписания" value="${D}"><button class="gh ib" data-a="dd" data-x="1" aria-label="Следующий день">${ic('r')}</button></div><span class="sp"></span><div class="planner-scope"><span class="scope-caption">Редактировать</span><select data-c="scope" aria-label="Область редактирования расписания">${[['date','Выбранная дата'],['dow','Шаблон дня недели'],['week','Общий шаблон']].map(([v,n])=>`<option value="${v}" ${v===scope?'selected':''}>${n}</option>`).join('')}</select></div></div><details class="planner-help"><summary>О шаблонах расписания</summary><p>${scope==='date'?'Изменения относятся только к выбранной дате и не затрагивают следующие недели.':'Изменения относятся к выбранному шаблону; исключения отдельных дат сохраняются.'} Общий шаблон применяется ежедневно, шаблон дня недели — в указанный день, исключение даты имеет приоритет.</p></details><div class="plan-layout"><div class="card">${Planner.clock()}<p class="help" style="text-align:center;margin-top:12px">Нажмите на свободное место кольца, чтобы создать блок.<br>Перетащите сектор, чтобы изменить его время.</p></div><div class="card"><div class="hd"><h3 style="margin:0">Расписание</h3><span class="pill">${Planner.list().length} блоков</span></div>${Planner.list().map((b,i)=>`<button class="block-row" data-a="editB" data-x="${i}"><span class="color-dot" style="background:${safeColor(b.color)}"></span><span class="sp"><b>${esc(b.name)}</b><span class="m sm" style="display:block">${tm(b.s)} — ${tm(b.e)}${b.e<b.s?' · до следующего дня':''}</span>${b.cat?`<span class="m sm">${esc(b.cat)}</span>`:''}${(b.tasks||[]).length?`<span class="m sm" style="display:block">${(b.tasks||[]).map(id=>esc(S.items.find(i=>i.id===id)?.title||'Удалённая задача')).join(', ')}</span>`:''}</span>${ic('edit')}</button>`).join('')||empty('clock','День ещё открыт','Добавьте первый блок или создайте общий шаблон расписания.')}<div class="row" style="margin-top:20px"><button class="gh" data-a="newB">${ic('plus')} Добавить блок</button>${scope==='date'&&Object.hasOwn(S.blocks.ex,D)||scope==='dow'&&Object.hasOwn(S.blocks.dow,pd(D).getDay())?'<button class="gh dg" data-a="resetSchedule">Сбросить исключение</button>':''}</div></div></div>`;
function setB(list,sc){if(sc==='date')S.blocks.ex[D]=list;else if(sc==='dow')S.blocks.dow[pd(D).getDay()]=list;else S.blocks.week=list;lg('Изменено расписание: '+Planner.label());save();render()}
function blockM(idx,start){const B=cl(Planner.list()),b=idx==null?{id:uid(),s:start??540,e:((start??540)+60)%1440,name:'',cat:'',color:'#5b8def',tasks:[]}:B[idx];let o=modal(idx==null?'Новый блок времени':'Изменить блок',`<div class="fr"><label>Название</label><input id="m_n" value="${esc(b.name)}" placeholder="Чему посвятить это время?"></div><div class="fr"><label>Начало и конец</label><input type="time" id="m_s" value="${tm(b.s)}"><input type="time" id="m_e" value="${tm(b.e)}"></div><p class="help">Если конец раньше начала, блок продолжается после полуночи. Пересечения допускаются.</p><div class="fr"><label>Категория</label>${catPick('m_c',b.cat)}</div><div class="fr"><label>Цвет</label><input type="color" id="m_k" value="${safeColor(b.color)}"></div><div class="fr"><label>Связанные задачи</label><div class="chips" id="m_ts">${items('task').filter(t=>!t.fin||(b.tasks||[]).includes(t.id)).map(t=>`<label><input type="checkbox" value="${t.id}" ${(b.tasks||[]).includes(t.id)?'checked':''}>${esc(t.title)}</label>`).join('')||'<p class="help">Создайте задачу в разделе «Задачи».</p>'}</div></div><div class="scope-note">Сохранить: ${esc(Planner.label())}. ${scope==='date'?'Только эта дата, не следующие недели.':'Другие исключения сохранятся.'}</div>`,()=>{const name=g('m_n').value.trim(),a=g('m_s').value,z=g('m_e').value;if(!name)throw Error('Введите название');if(!a||!z||a===z)throw Error('Укажите различающиеся начало и конец');const nb={...b,name,s:mt(a),e:mt(z),cat:g('m_c').dataset.v||'',color:safeColor(g('m_k').value),tasks:[...g('m_ts').querySelectorAll('input:checked')].map(x=>x.value)};if(idx==null)B.push(nb);else B[idx]=nb;setB(B,scope)},idx!=null?'<button class="dg" id="del_block">'+ic('trash')+' Удалить</button>':'');o.querySelector('#del_block')?.addEventListener('click',()=>{B.splice(idx,1);o.close();setB(B,scope)})}
function after(){const c=g('clk');if(!c)return;let dr=null;const mins=e=>{const r=c.getBoundingClientRect(),x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;let a=Math.atan2(y,x)+Math.PI/2;if(a<0)a+=Math.PI*2;return a/(Math.PI*2)*1440};c.onpointerdown=e=>{const path=e.target.closest('.blk');if(!path){const r=c.getBoundingClientRect(),dist=Math.hypot(e.clientX-r.left-r.width/2,e.clientY-r.top-r.height/2)/(r.width/352);if(dist>=85&&dist<=140){blockM(null,Math.round(mins(e)/15)*15%1440)}return}const B=cl(Planner.list()),i=+path.dataset.i;dr={i,B,m0:mins(e),s:B[i].s,len:(B[i].e-B[i].s+1440)%1440||1440,mv:false,path};c.setPointerCapture(e.pointerId)};c.onpointermove=e=>{if(!dr)return;let d=((mins(e)-dr.m0+2160)%1440)-720;if(Math.abs(d)>10||dr.mv){dr.mv=true;const b=dr.B[dr.i];b.s=((Math.round((dr.s+d)/15)*15)%1440+1440)%1440;b.e=(b.s+dr.len)%1440;dr.path.setAttribute('d',arc(b.s,b.e,87,137))}};c.onpointerup=()=>{if(!dr)return;const d=dr;dr=null;if(d.mv){if(scope!=='date'&&!confirm('Изменить '+Planner.label()+'? Исключения дат не затрагиваются.'))return render();setB(d.B,scope)}else blockM(d.i)};c.onpointercancel=()=>{dr=null;render()};c.onkeydown=e=>{const path=e.target.closest('.blk');if(path&&['Enter',' '].includes(e.key)){e.preventDefault();blockM(+path.dataset.i)}}}
A.resetSchedule=()=>{if(confirm('Удалить исключение и вернуться к унаследованному шаблону?')){if(scope==='date')delete S.blocks.ex[D];else if(scope==='dow')delete S.blocks.dow[pd(D).getDay()];save();render()}};

