const diamonds=(n,sign=true)=>`<span class="diamond-value">${sign?dm(+n.toFixed(2)):+n.toFixed(2)}${ic('diamond')}</span>`;
V.cal=()=>{const[y,m]=cm.split('-').map(Number),offset=(new Date(y,m-1,1).getDay()+6)%7,count=new Date(y,m,0).getDate(),by={};S.ledger.forEach(l=>{const b=by[l.date]=by[l.date]||{p:0,n:0};b[l.amt>=0?'p':'n']+=l.amt});
 let cells='<span class="calendar-blank" aria-hidden="true"></span>'.repeat(offset);
 for(let d=1;d<=count;d++){const k=cm+'-'+p2(d),b=by[k]||{p:0,n:0},tasks=S.items.filter(i=>i.kind==='task'&&i.due===k),pending=tasks.filter(t=>!t.fin),hasEntry=!!S.entries[k];
 cells+=`<button class="cd ${D===k?'on':''} ${k===today()?'t':''}" data-a="pick" data-x="${k}" aria-pressed="${D===k}" aria-label="${k}, ${pending.length} задач с дедлайном, награды ${b.p}, штрафы ${b.n}"><span class="calendar-date">${d}${hasEntry?`<span class="calendar-entry" title="Запись дневника">${ic('book')}</span>`:''}</span><span class="calendar-task-labels">${pending.slice(0,2).map(t=>`<span class="calendar-task-label" title="${esc(t.title)}">${ic('clock')}<span>${esc(t.title)}</span></span>`).join('')}${pending.length>2?`<span class="calendar-more">Ещё ${pending.length-2}</span>`:''}</span>${pending.length?`<span class="calendar-task-count">${ic('check')} ${pending.length}</span>`:''}<span class="calendar-money">${b.p?`<span class="g">${diamonds(b.p)}</span>`:''}${b.n?`<span class="rd">${diamonds(b.n)}</span>`:''}</span></button>`}
 const L=S.ledger.filter(l=>l.date===D),tasks=S.items.filter(i=>i.kind==='task'&&i.due===D);return pageHead('Календарь','')+`<div class="calendar-toolbar"><div class="row"><button class="gh ib" data-a="cmv" data-x="-1" aria-label="Предыдущий месяц">${ic('l')}</button><h3>${new Date(y,m-1,1).toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</h3><button class="gh ib" data-a="cmv" data-x="1" aria-label="Следующий месяц">${ic('r')}</button></div><button data-a="calToday">Сегодня</button></div><div class="calendar-layout"><section class="calendar-month"><div class="cg">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(n=>`<span class="day-head">${n}</span>`).join('')}${cells}</div></section><section class="card calendar-agenda"><div class="agenda-heading"><h3>${pd(D).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</h3><span class="pill blue">${diamonds(bal(L))}</span></div><h4>Дедлайны <span class="m">${tasks.length}</span></h4>${tasks.map(i=>`<article class="agenda-task"><button class="gh ib" data-a="done" data-x="${i.id}" aria-label="${i.fin?'Отменить выполнение':'Выполнить'}: ${esc(i.title)}">${ic(i.fin?'check-circle':'check-square')}</button><div><b>${esc(i.title)}</b><p class="m sm">${esc(i.cat||'Без категории')} · ${i.fin?'Выполнено':i.due<today()?'Просрочено':'До конца дня'}</p></div><button class="gh ib" data-a="editI" data-x="${i.id}" aria-label="Изменить задачу">${ic('edit')}</button></article>`).join('')||'<p class="agenda-empty">Нет задач с дедлайном на этот день.</p>'}${L.length?`<h4>Алмазы</h4>${L.map(l=>`<div class="agenda-operation"><span>${esc(l.why)}</span><b class="${l.amt>=0?'g':'rd'}">${diamonds(l.amt)}</b></div>`).join('')}`:''}<div class="agenda-actions"><button data-a="goDiary">${ic('book')} Запись дня</button><button data-a="goPlan">${ic('clock')} Расписание</button></div></section></div>`};
A.pick=x=>{extra=[];D=x;Diary.preview=false;render()};A.calToday=()=>{extra=[];D=today();cm=D.slice(0,7);render()};
let rewardFilter='all';
V.rewards=()=>{const list=[...S.ledger].reverse().filter(l=>rewardFilter==='all'||rewardFilter==='positive'&&l.amt>0||rewardFilter==='negative'&&l.amt<0);return pageHead('Награды и штрафы','Только те стимулы, которые работают для вас.',`<button data-a="rulesM">${ic('cfg')} Общие правила</button>`,'ВАШИ ПРАВИЛА')+`<div class="hero"><div class="gem">${ic('diamond')}</div><div><div class="big">${+bal(S.ledger).toFixed(2)}</div><div class="m sm">алмазов на балансе</div></div><span class="sp"></span><button class="pri" data-a="manualM">${ic('plus')} Корректировка</button></div><div class="row"><div class="seg">${[['all','Все операции'],['positive','Награды'],['negative','Штрафы']].map(([v,n])=>`<button data-a="rewardFilter" data-x="${v}" class="${rewardFilter===v?'on':''}">${n}</button>`).join('')}</div></div><section class="card">${list.map(l=>`<div class="it ledger-row"><span class="m sm">${esc(l.date)}</span><div class="sp"><b>${esc(l.why)}</b><p class="m sm">${esc(l.cat||'Без категории')} · ${{on:'в срок',late:'позднее',miss:'пропуск',move:'перенос',manual:'ручная операция'}[l.k]||esc(l.k)}</p></div><b class="${l.amt>0?'g':'rd'}">${dm(l.amt)} ${ic('diamond')}</b><button class="gh ib" data-a="delL" data-x="${l.id}" title="Отменить операцию без повторного начисления">${ic('x')}</button></div>`).join('')||empty('diamond','Баланс начинается с ваших правил','Награды необязательны. По умолчанию суммы равны нулю.')}</section>`};A.rewardFilter=x=>{rewardFilter=x;render()};
A.delL=id=>{if(confirm('Отменить эту операцию? Повторно автоматически начисляться она не будет.')){const l=S.ledger.find(l=>l.id===id);if(l.ref)S.skip.push(l.ref);S.ledger=S.ledger.filter(l=>l.id!==id);lg('Отменена операция: '+l.why);save();render()}};
function rulesM(){document.querySelectorAll('.ov').forEach(x=>x.remove());const o=modal('Общие правила',`<p class="help">Никакая система не обязательна. Положительная сумма добавляет алмазы, отрицательная — списывает. Индивидуальные правила задачи или привычки имеют приоритет. Изменения влияют только на новые события, не пересчитывают историю.</p>${['task','habit','skill'].map(k=>{const r=S.rules[k];return`<section class="rs"><div class="hd"><h3 style="margin:0">${{task:'Задачи',habit:'Привычки',skill:'Уровни навыков'}[k]}</h3><label><input id="r_${k}_en" type="checkbox" ${r.en?'checked':''}> Включено</label></div><div class="grid">${(k==='skill'?[['on','За уровень']]:[['on','В срок'],['late','С опозданием'],['miss','Пропуск'],['move','Перенос'],['grace','Отсрочка, дней']]).map(([f,l])=>`<label>${l}<input type="number" id="r_${k}_${f}" step="${f==='grace'?'1':'any'}" ${f==='grace'?'min="0"':''} value="${r[f]??0}"></label>`).join('')}</div></section>`}).join('')}<section class="rs"><h3>Исключения категорий</h3>${S.cats.map((c,i)=>`<div class="it"><span class="sp">${esc(c)}</span><label><input id="r_cat_${i}" type="checkbox" ${S.offCats.includes(c)?'checked':''}> Без наград и штрафов</label></div>`).join('')||'<p class="help">Категории можно создать в задаче, привычке или блоке времени.</p>'}</section><p class="help">Просрочка фиксируется при открытии приложения и обновлении дня. Для поздней привычки штраф за пропуск заменяется поздней наградой; у задачи разовый штраф за дедлайн и награда за последующее выполнение — отдельные события.</p>`,()=>{const rules=cl(S.rules);for(const k of ['task','habit','skill']){rules[k].en=g('r_'+k+'_en').checked?1:0;for(const f of k==='skill'?['on']:['on','late','miss','move','grace']){const v=+g('r_'+k+'_'+f).value;if(!Number.isFinite(v)||f==='grace'&&(!Number.isInteger(v)||v<0))throw Error('Проверьте суммы и отсрочку');rules[k][f]=v}}S.rules=rules;S.offCats=S.cats.filter((c,i)=>g('r_cat_'+i).checked);lg('Изменены правила баланса');save();render()});return o}
/* Accessible tabular analytics: observed values only, with explicit gaps. */
V.stats=()=>{const L=S.ledger.filter(l=>(!sf.from||l.date>=sf.from)&&(!sf.to||l.date<=sf.to)&&(!sf.cat||l.cat===sf.cat)),pos=bal(L.filter(l=>l.amt>0)),neg=bal(L.filter(l=>l.amt<0)),by={},cats={};L.forEach(l=>{const d=by[l.date]=by[l.date]||{p:0,n:0};d[l.amt>=0?'p':'n']+=l.amt;cats[l.cat||'Без категории']=(cats[l.cat||'Без категории']||0)+l.amt});let cum=0;const rows=Object.keys(by).sort().map(d=>{const b=by[d];cum+=b.p+b.n;return`<tr><td data-label="Дата">${pd(d).toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</td><td data-label="Награды" class="g">${diamonds(b.p)}</td><td data-label="Штрафы" class="rd">${diamonds(b.n)}</td><td data-label="Итог дня">${diamonds(b.p+b.n)}</td><td data-label="Накопление">${diamonds(cum,false)}</td></tr>`}).join('');const numeric=S.fields.filter(f=>['number','rating'].includes(f.type)),field=numeric.find(f=>f.id===sf.fld),data=field?Object.keys(S.entries).sort().filter(d=>(!sf.from||d>=sf.from)&&(!sf.to||d<=sf.to)).map(d=>({d,v:parseMd(S.entries[d]).fm[field.id]})).filter(x=>typeof x.v==='number'&&Number.isFinite(x.v)):[];return pageHead('Статистика','Наблюдайте за изменениями — без обязательных оценок.','','НАБЛЮДЕНИЯ')+`<div class="row stats-filters"><label class="sm m">С <input aria-label="Начало периода" type="date" value="${sf.from}" data-c="sf" data-k="from"></label><label class="sm m">По <input aria-label="Конец периода" type="date" value="${sf.to}" data-c="sf" data-k="to"></label><select aria-label="Категория статистики" data-c="sf" data-k="cat"><option value="">Все категории</option>${S.cats.map(c=>`<option ${c===sf.cat?'selected':''}>${esc(c)}</option>`).join('')}</select><button class="gh" data-a="resetStats">Сбросить</button></div>${sf.from&&sf.to&&sf.from>sf.to?'<p class="rd">Начало периода позже окончания.</p>':''}<div class="stat-grid"><div class="stat-box"><span class="sm m">Изменение</span><strong>${diamonds(bal(L))}</strong><span class="sm m">алмазов за период</span></div><div class="stat-box"><span class="sm m">Награды</span><strong class="g">${diamonds(pos)}</strong><span class="sm m">${L.filter(l=>l.amt>0).length} операций</span></div><div class="stat-box"><span class="sm m">Штрафы</span><strong class="rd">${diamonds(neg)}</strong><span class="sm m">${L.filter(l=>l.amt<0).length} операций</span></div></div><div class="card"><h3>Динамика по дням</h3><p class="help">Накопление — изменение за выбранный период.</p>${rows?`<div class="daily-table"><table><caption class="sr-only">Динамика алмазов по дням</caption><thead><tr><th>Дата</th><th>Награды</th><th>Штрафы</th><th>Итог дня</th><th>Накопление</th></tr></thead><tbody>${rows}</tbody></table></div>`:empty('chart','Пока нет операций','Выберите другой период или настройте правила начисления.')}</div><div class="card"><h3>По категориям</h3>${Object.entries(cats).map(([c,v])=>`<div class="it"><span class="sp">${esc(c)}</span><b>${dm(+v.toFixed(2))} ${ic('diamond')}</b></div>`).join('')||'<p class="m sm">Нет данных.</p>'}</div><div class="card"><div class="hd"><h3 style="margin:0">Поля дневника</h3><select data-c="sf" data-k="fld" aria-label="Числовое поле"><option value="">Выберите поле</option>${numeric.map(f=>`<option value="${esc(f.id)}" ${sf.fld===f.id?'selected':''}>${esc(f.name)}</option>`).join('')}</select></div><p class="help">Период дат применяется к дневнику. Категории относятся только к операциям алмазов. Пустые поля не считаются нулями.</p>${field&&data.length?`<div class="row"><span class="pill">Среднее ${(data.reduce((a,x)=>a+x.v,0)/data.length).toLocaleString('ru-RU',{maximumFractionDigits:2})}</span><span class="pill">Минимум ${Math.min(...data.map(x=>x.v))}</span><span class="pill">Максимум ${Math.max(...data.map(x=>x.v))}</span><span class="pill">${data.length} записей</span></div><div class="table-scroll"><table><thead><tr><th>Дата</th><th>${esc(field.name)}</th></tr></thead><tbody>${data.map(x=>`<tr><td>${x.d}</td><td>${x.v}</td></tr>`).join('')}</tbody></table></div>`:'<p class="m sm">Числовых значений в выбранном поле и периоде пока нет.</p>'}</div>`};A.resetStats=()=>{sf={from:'',to:'',cat:'',fld:''};render()};

/* Interchange: true ZIP vault, one Markdown/YAML file per diary record. */
const Vault={
 download(name,data,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([data],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)},
 state(){const{entries,...state}=S;return state},
 files(){saveE(1);const files={'data/state.yaml':fflate.strToU8(jsyaml.dump(this.state(),{noRefs:true,lineWidth:120,sortKeys:false})),'manifest.json':fflate.strToU8(JSON.stringify({app:'LifeOS',version:APP_VERSION,exportedAt:new Date().toISOString(),entries:Object.keys(S.entries).length},null,2)),'README.md':fflate.strToU8('# LifeOS vault\n\nДневник: отдельные файлы diary/YYYY-MM-DD.md с YAML frontmatter.\nНастройки, схемы полей, задачи, навыки, расписания и журнал алмазов: data/state.yaml.\nZIP можно импортировать целиком в LifeOS. Папку можно открыть в Obsidian.\nПеред любым изменением формата делайте резервную копию.\n')};Object.entries(S.entries).forEach(([d,t])=>files['diary/'+d+'.md']=fflate.strToU8(t));return files},
 async export(){try{this.download('LifeOS-vault-'+today()+'.zip',fflate.zipSync(this.files(),{level:6}),'application/zip');lg('Экспортирован ZIP-хранилище');save();toast('ZIP содержит отдельные Markdown-записи и настройки YAML')}catch(e){toast('Экспорт не выполнен: '+e.message)}},
 async chooseFolder(){if(!window.showDirectoryPicker)return toast('Запись в папку недоступна в этом браузере. Используйте ZIP-экспорт.');try{const h=await window.showDirectoryPicker({mode:'readwrite'});if(!confirm('Записать данные LifeOS в «'+h.name+'»? Одноимённые файлы diary/*.md и data/state.yaml будут заменены. Другие файлы не удаляются.'))return;Store.folder=h;await this.sync();render()}catch(e){if(e.name!=='AbortError')toast('Нет доступа к папке. Используйте ZIP: '+e.message)}},
 async writePath(path,data){if(!Store.folder)return;const parts=path.split('/'),name=parts.pop();let d=Store.folder;for(const p of parts)d=await d.getDirectoryHandle(p,{create:true});const fh=await d.getFileHandle(name,{create:true}),w=await fh.createWritable();try{await w.write(data);await w.close()}catch(e){await w.abort().catch(()=>{});throw e}},
 async writeEntry(d,text){await this.writePath('diary/'+d+'.md',text)},
 async sync(){try{const files=this.files();for(const[p,t]of Object.entries(files))await this.writePath(p,t);toast('Файлы записаны в папку. Удалённые в приложении файлы из папки не удаляются.')}catch(e){toast('Не все файлы записаны: '+e.message+' Сделайте ZIP-копию.')}},
 async read(files){let entries={},state=null;for(const f of files){if(f.size>64*1024*1024)throw Error('Файл больше 64 МБ: '+f.name);if(/\.zip$/i.test(f.name)){const extracted=fflate.unzipSync(new Uint8Array(await f.arrayBuffer()),{filter:info=>info.originalSize<=64*1024*1024&&/^(diary\/[^/]+\.md|data\/state.yaml|manifest.json)$/.test(info.name)});for(const[p,b]of Object.entries(extracted)){const t=fflate.strFromU8(b);if(p==='data/state.yaml')state=jsyaml.load(t,{schema:jsyaml.JSON_SCHEMA});else if(p.startsWith('diary/'))this.readEntry(p,t,entries)}}else{const text=await f.text();if(/(?:^|\/)state\.(?:yaml|yml|json)$/i.test(f.webkitRelativePath||f.name)){state=/\.json$/i.test(f.name)?JSON.parse(text):jsyaml.load(text,{schema:jsyaml.JSON_SCHEMA})}else{const parts=text.replace(/\r\n/g,'\n').split(/<!-- file: (.+?) -->\n/);if(parts.length>1){for(let i=1;i<parts.length;i+=2){if(parts[i].endsWith('state.yaml'))state=jsyaml.load(parts[i+1],{schema:jsyaml.JSON_SCHEMA});else if(parts[i].endsWith('.md'))this.readEntry(parts[i],parts[i+1].replace(/\n$/,''),entries)}}else if(/\.md$/i.test(f.name))this.readEntry(f.name,text,entries)}}}if(!Object.keys(entries).length&&!state)throw Error('Не найдено записей Markdown или data/state.yaml');if(state){if(!state||typeof state!=='object'||Array.isArray(state))throw Error('Некорректный state.yaml');if(state.entries){entries={...state.entries,...entries};delete state.entries}}const candidate=normalise({...state||def(),entries});return{candidate,hasState:!!state}},
 readEntry(path,text,entries){const parsed=parseMd(text),d=parsed.fm.date||/(\d{4}-\d\d-\d\d)/.exec(path)?.[1];if(!validDate(d))throw Error('Не найдена корректная дата в '+path);entries[d]=text},
 async import(files){saveE(1);try{const{candidate,hasState}=await this.read(files),collisions=Object.keys(candidate.entries).filter(d=>Object.hasOwn(S.entries,d));modal('Проверка импорта',`<div class="tip"><b>Файлы прочитаны и проверены.</b><p style="margin:8px 0 0">Записей: ${Object.keys(candidate.entries).length}. Совпадающих дат: ${collisions.length}.${hasState?` Задач и привычек: ${candidate.items.length}. Навыков: ${candidate.skills.length}.`:' Без файла настроек.'}</p></div><div class="fr"><label>Как импортировать</label><select id="import_mode"><option value="merge">Объединить с текущими данными</option><option value="replace">Полностью заменить хранилище</option></select></div><div class="fr"><label>При совпадении даты / идентификатора</label><select id="import_conflict"><option value="keep">Оставить текущую версию</option><option value="incoming">Взять импортируемую версию</option></select></div><p class="help">Перед заменой настоятельно рекомендуем скачать текущую ZIP-копию. Импорт применяется целиком только после проверки. Объединение настроек: текущие настройки остаются; новые категории и сущности добавляются.</p><button data-a="exp">${ic('archive')} Скачать текущую копию</button>`,()=>{const replace=g('import_mode').value==='replace',incoming=g('import_conflict').value==='incoming';let next;if(replace)next=candidate;else{next=cl(S);next.entries=incoming?{...S.entries,...candidate.entries}:{...candidate.entries,...S.entries};if(hasState){for(const key of ['fields','items','skills','ledger']){const map=new Map(next[key].map(x=>[x.id,x]));for(const x of candidate[key])if(!map.has(x.id)||incoming)map.set(x.id,x);next[key]=[...map.values()]}for(const k of ['cats','offCats','skip'])next[k]=[...new Set([...next[k],...candidate[k]])];const tm=new Map(next.tpls.map(t=>[t.n,t]));for(const t of candidate.tpls)if(!tm.has(t.n)||incoming)tm.set(t.n,t);next.tpls=[...tm.values()]}}for(const text of Object.values(next.entries)){const{fm}=parseMd(text);for(const[k,v]of Object.entries(fm)){if(['date','_fields','_templates'].includes(k)||next.fields.some(f=>f.id===k)||!/^[\p{L}\p{N}_-]+$/u.test(k))continue;next.fields.push({id:k,name:k,type:typeof v==='number'?'number':typeof v==='boolean'?'check':Array.isArray(v)&&v.every(x=>typeof x==='string')?'list':typeof v==='object'?'json':'text',when:'manual',opts:[]})}}next=normalise(next);if(replace&&!confirm('Полностью заменить данные приложения импортом?'))return false;S=next;Store.blocked=false;Store.conflict=false;document.documentElement.dataset.theme=S.settings.theme;extra=[];lg('Импортировано записей: '+Object.keys(candidate.entries).length);save();render();toast('Импорт завершён')},'','Импортировать')}catch(e){toast('Импорт отменён, данные не изменены: '+e.message)}}
};
