A.manualM=()=>modal('Операция с алмазами',`<div class="fr"><label>Сумма (минус — списание)</label><input type="number" step="any" id="ma"></div><div class="fr"><label>Название / причина</label><input id="mw" placeholder="Например, награда за большой проект"></div><div class="fr"><label>Дата</label><input type="date" id="mld" value="${today()}"></div><div class="fr"><label>Категория</label>${catPick('mlc','')}</div>`,()=>{const v=+g('ma').value;if(!Number.isFinite(v)||!v)throw Error('Введите ненулевую сумму');if(!validDate(g('mld').value))throw Error('Проверьте дату');const why=g('mw').value.trim();if(!why)throw Error('Добавьте причину операции');S.ledger.push({id:uid(),date:g('mld').value,amt:v,why,cat:g('mlc').dataset.v||'',k:'manual'});lg('Ручная операция: '+dm(v)+' '+why);save();render()});
V.profile=()=>pageHead('Мой профиль','Ваши данные принадлежат вам. И остаются под вашим контролем.','','ЛИЧНОЕ')+`<div class="two-col"><div class="stack"><section class="card"><div class="row" style="margin:0 0 20px"><div class="gem">${ic('user')}</div><div><h3 style="margin:0">${esc(S.name==='Я'?'Моё пространство':S.name)}</h3><span class="m sm">LifeOS · локальное хранилище</span></div></div><div class="fr"><label for="profile-name">Имя</label><input id="profile-name" data-c="name" value="${esc(S.name)}"></div><div class="fr"><label for="theme">Оформление</label><select id="theme" data-c="theme"><option value="system" ${S.settings.theme==='system'?'selected':''}>Как в системе</option><option value="light" ${S.settings.theme==='light'?'selected':''}>Светлое</option><option value="dark" ${S.settings.theme==='dark'?'selected':''}>Тёмное</option></select></div><div class="grid"><span class="pill">${Object.keys(S.entries).length} записей</span><span class="pill">${items('task').length} задач</span><span class="pill">${items('habit').length} привычек</span><span class="pill">${S.skills.length} навыков</span></div></section><section class="card"><h3>Хранилище и резервные копии</h3><p class="m sm">Данные сохраняются в браузере: основная локальная копия и до 12 снимков в IndexedDB. Очистка данных браузера удалит и эти копии. Регулярно скачивайте ZIP или записывайте папку на диск.</p><div class="row"><button class="pri" data-a="exp">${ic('archive')} Экспорт ZIP</button><button data-a="impB">${ic('ul')} Импорт MD / YAML / ZIP</button><button data-a="backups">${ic('arrow-counter-clockwise')} Снимки</button></div><div class="row"><button data-a="folder">${ic('folder-open')} Записать в папку</button>${Store.folder?'<button data-a="syncFolder">Синхронизировать папку</button>':''}</div><p class="help">ZIP содержит diary/YYYY-MM-DD.md и data/state.yaml; его можно распаковать и открыть как хранилище Obsidian. Запись в папку — дополнительная возможность Chromium в безопасном контексте. После подключения заметки записываются автоматически; остальные данные — по кнопке синхронизации. Облачной синхронизации и фоновой работы при закрытом приложении нет.</p><div class="row"><button class="gh" data-a="guide">${ic('book-open')} Как пользоваться</button><span class="sp"></span><button class="gh dg" data-a="reset">${ic('trash')} Удалить данные</button></div></section><section class="card"><h3>История активности</h3>${S.log.slice(0,150).map(l=>`<div class="it"><span class="m sm">${new Date(l.t).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</span><span class="sp sm">${esc(l.x)}</span></div>`).join('')||'<p class="m sm">Здесь появятся ваши действия.</p>'}</section></div><aside class="stack"><div class="tip">${ic('shield-check')}<h3>Без сервера и аккаунта</h3><p>LifeOS работает офлайн. Иконки Phosphor и библиотеки встроены — внешние сервисы не загружаются.</p><p style="margin-bottom:0">Для постоянной работы открывайте приложение по одному адресу и в одном профиле браузера.</p></div><section class="card"><div class="section-tag">Баланс</div><div class="big">${+bal(S.ledger).toFixed(2)}</div><div class="m sm" style="margin-top:8px">алмазов · ваши правила</div><button class="gh" data-nav="rewards" style="margin-top:16px;padding-left:0">История операций ${ic('arrow-up-right')}</button></section></aside></div>`;
C.theme=v=>{S.settings.theme=v;document.documentElement.dataset.theme=v;save()};
A.guide=()=>modal('Как устроен LifeOS',`<section class="rs"><h3>1. Дневник и свои поля</h3><p>Создайте поля: число, текст, дата, диапазон, список, выбор, чекбокс, оценка, время, ссылка или JSON. Назначайте ежедневно, по дням недели или разово. В «Поля и шаблоны» можно собрать набор полей и Markdown-текст с расписанием. Изменения записи сохраняются автоматически.</p></section><section class="rs"><h3>2. Задачи, привычки и алмазы</h3><p>Задачи повторяются после выполнения. Привычки — по интервалу и дням недели. Общие правила находятся в наградах, индивидуальные — в настройках задачи. Штрафы вводятся отрицательными числами. Исключения и отключение наград/штрафов независимы. Пропуски обнаруживаются, когда приложение открыто.</p></section><section class="rs"><h3>3. Время</h3><p>Выберите область: дата, день недели или общий шаблон. Нажмите свободное место кольца для создания блока; перетаскивайте сектор для сдвига. Точные начало и конец доступны в редакторе, в том числе на телефоне. Дата никогда не изменяет будущие недели.</p></section><section class="rs"><h3>4. Навыки</h3><p>Опишите от 3 до 100 проверяемых результатов и свою последовательность уровней. По умолчанию уровень подтверждается вручную. Канвас — дополнительное представление; обычное дерево доступно рядом. Доказательства и изменения хранятся в истории. Расчёт родителя выбираете вы.</p></section><section class="rs"><h3>5. Данные</h3><p>Регулярно делайте ZIP-экспорт: каждая запись — отдельный Markdown с YAML. Импорт поддерживает предпросмотр и выбор конфликтов. Локальные снимки не заменяют внешнюю резервную копию. Для запуска из исходников используйте python3 -m http.server 8080 и один и тот же адрес.</p></section>`,()=>{},'','Понятно');
A.reset=()=>modal('Удалить данные приложения',`<p>Удалятся все записи, задачи, навыки, операции и локальные снимки этого приложения. Файлы на диске не удаляются.</p><button data-a="exp">${ic('archive')} Сначала скачать ZIP-копию</button><div class="fr"><label>Введите УДАЛИТЬ для подтверждения</label><input id="reset_confirm" autocomplete="off"></div>`,async()=>{if(g('reset_confirm').value!=='УДАЛИТЬ')throw Error('Введите УДАЛИТЬ');await Store.queue;if(Store.db)await new Promise((res,rej)=>{const tx=Store.db.transaction(['snapshots','files'],'readwrite');tx.objectStore('snapshots').clear();tx.objectStore('files').clear();tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});localStorage.removeItem(KEY);S=normalise(def());Store.blocked=false;Store.conflict=false;extra=[];D=today();save();view='diary';render();toast('Данные удалены')},'','Удалить всё');
// Make storage states visible even when saving a malformed structured field fails.
window.addEventListener('error',e=>{console.error(e.error);toast('Ошибка приложения. Текущие данные не удалены; сделайте экспорт.')});
setInterval(()=>{if(S&&!Store.conflict&&!Store.blocked&&!g('lifeos-shell').hidden){scan();Store.status()}},60000);

/* Host-owned repository adapter. No owner credential or raw network API enters this frame. */
const Delta=window.DeltaLifeOS,dc=(op,args={})=>Delta.host.call('lifeos.'+op,args);
let remoteRevision=0,nextSnapshot=null,flushing=false,refreshing=false,editGeneration=0,navigationGeneration=0;
const draftKey="delta-lifeos.pending:"+Delta.parentOrigin;
function keepDraft(state){try{localStorage.setItem(draftKey,JSON.stringify({state,baseRevision:remoteRevision,at:Date.now()}))}catch{}}
function clearDraft(id){try{const d=JSON.parse(localStorage.getItem(draftKey)||"null");if(d?.state?._writeId===id)localStorage.removeItem(draftKey)}catch{}}
async function readRemote(){let last;for(let retry=0;retry<3;retry++){try{let text='',offset=0,rev;do{const page=await dc('workspace_read',{offset,...(rev==null?{}:{revision:rev})});rev=page.revision;text+=page.data;offset=page.nextOffset;}while(offset!=null);return{state:normalise(JSON.parse(text)),revision:rev}}catch(e){last=e;if(e.message!=='conflict'&&e.code!=='conflict')throw e}}throw last}
async function writeRemote(snapshot){const text=JSON.stringify(snapshot),bytes=new TextEncoder().encode(text),sha256=Delta.hash(bytes),chunks=[];for(let i=0;i<text.length;i+=10000)chunks.push(text.slice(i,i+10000));const begin=await dc('workspace_begin',{revision:remoteRevision,parts:chunks.length,sha256});for(let i=0;i<chunks.length;i++)await dc('workspace_chunk',{uploadId:begin.uploadId,index:i,data:chunks[i]});const result=await dc('workspace_commit',{uploadId:begin.uploadId,revision:remoteRevision,requestId:Delta.id()});remoteRevision=result.revision;}
Store.status=function(){document.querySelectorAll('#lifeos-shell .save-state').forEach(el=>{el.innerHTML=ic(Store.conflict||!Store.ok||Store.formError?'warning':Store.pending?'clock':'cloud-check')+'<span>'+(Store.conflict?'Конфликт изменений':Store.formError?'Проверьте поля':!Store.ok?'Не сохранено в Delta':Store.pending?'Сохранение…':'Сохранено в Delta')+'</span>';el.title=Store.lastError||'';el.style.color=Store.conflict||!Store.ok||Store.formError?'var(--r)':''})};
async function flushDelta(){if(flushing)return Store.queue;if(!nextSnapshot)return;flushing=true;Store.pending=1;Store.status();Store.queue=(async()=>{while(nextSnapshot){const data=nextSnapshot;nextSnapshot=null;try{try{await writeRemote(data)}catch(e){if(e.message!=="host_timeout"&&e.message!=="unavailable")throw e;const fresh=await readRemote();if(fresh.state._writeId!==data._writeId)throw e;remoteRevision=fresh.revision;}clearDraft(data._writeId);try{localStorage.setItem(KEY,JSON.stringify(data))}catch{}Store.ok=true;Store.lastError=null;Store.conflict=false}catch(e){nextSnapshot=nextSnapshot||data;Store.ok=false;Store.lastError=String(e.code||e.message||'operation_failed').slice(0,200);Store.conflict=e.code==='conflict'||e.message==='conflict';toast(Store.conflict?'Данные изменились. Экспортируйте несохранённую версию и обновите данные.':'Delta недоступна. Изменения остаются в памяти; скачайте ZIP или повторите сохранение.');break}}})().finally(()=>{flushing=false;Store.pending=nextSnapshot?1:0;Store.status()});return Store.queue}
function save(){if(Store.conflict||Store.blocked){Store.ok=false;Store.status();toast('Сначала разрешите конфликт или восстановите подключение. Текущую версию можно экспортировать.');return false}S._savedAt=Date.now();S._writeId=Delta.id();editGeneration++;nextSnapshot=cl(S);keepDraft(nextSnapshot);Store.pending=1;Store.status();clearTimeout(Store.syncTimer);Store.syncTimer=setTimeout(()=>void flushDelta(),180);return true}
async function refreshDelta(){if(view.startsWith('native_')||refreshing||flushing||nextSnapshot||Diary.timer||document.querySelector('.ov'))return;refreshing=true;const generation=editGeneration;try{const fresh=await readRemote();if(generation!==editGeneration||flushing||nextSnapshot||Diary.timer)return;if(fresh.revision!==remoteRevision){remoteRevision=fresh.revision;S=fresh.state;extra=[];render()}}catch(e){toast('Не удалось обновить данные Delta')}finally{refreshing=false}}
async function boot(){Store.db=null;Store.blocked=false;Store.ok=true;try{const fresh=await readRemote();S=fresh.state;remoteRevision=fresh.revision;const map={journal:'diary',calendar:'cal',planner:'plan',statistics:'stats'};view=map[Delta.surface]||Delta.surface||'diary';if(!V[view])view='diary';document.documentElement.dataset.theme=Delta.context.theme;scan();render();document.documentElement.dataset.lifeosConnected="true";Store.status();offerDraft()}catch(e){g('main').innerHTML='<section class="card" role="alert"><h2>Delta LifeOS</h2><p>Сервис LifeOS недоступен. Проверьте установку и регистрацию плагина на выбранном узле.</p><button id="delta-retry">Повторить</button></section>';g('delta-retry').onclick=boot}}
function offerDraft(){let d;try{d=JSON.parse(localStorage.getItem(draftKey)||"null")}catch{return}if(!d?.state||!d.state._writeId)return;if(d.state._writeId===S._writeId){clearDraft(d.state._writeId);return}modal('Несохранённый черновик',`<p>Найден локальный черновик от ${esc(new Date(d.at).toLocaleString('ru-RU'))}. Серверная версия не заменена.</p><p class="m sm">Восстановление загрузит черновик в редактор. При изменении серверной версии автоматическая запись будет заблокирована.</p>`,()=>{S=normalise(d.state);editGeneration++;nextSnapshot=cl(S);remoteRevision=d.baseRevision;Store.conflict=false;Store.pending=1;Store.ok=false;render();},'<button class="gh" id="download-draft">Скачать черновик</button>','Восстановить').querySelector('#download-draft').onclick=()=>download('lifeos-unsaved.json',JSON.stringify(d,null,2));}
function capturePendingEditor(){try{saveE(1);if(nextSnapshot)keepDraft(nextSnapshot)}catch(e){Store.formError=true;Store.status()}}
window.addEventListener('blur',capturePendingEditor);
window.addEventListener('pagehide',capturePendingEditor);
document.addEventListener('visibilitychange',()=>{if(document.hidden)capturePendingEditor()});
