A.reloadDelta=async()=>{if((nextSnapshot||Store.conflict||!Store.ok)&&!confirm('Загрузить данные с сервера? Несохранённая локальная версия будет заменена. Сначала сделайте ZIP-экспорт.'))return;nextSnapshot=null;Store.conflict=false;Store.pending=0;Store.ok=true;const fresh=await readRemote();remoteRevision=fresh.revision;S=fresh.state;extra=[];render()};
V.profile=()=>pageHead('Профиль','')+`<div class="two-col"><section class="card"><div class="fr"><label>Имя</label><input data-c="name" value="${esc(S.name)}"></div><div class="row"><span class="pill">${Object.keys(S.entries).length} записей</span><span class="pill">${items('task').length} задач</span><span class="pill">${S.skills.length} навыков</span></div><div class="row"><button data-a="exp">${ic('archive')} Экспорт ZIP</button><button data-a="impB">${ic('ul')} Импорт</button></div><p class="help">Данные хранятся в Delta Storage. ZIP содержит Markdown-записи и YAML-настройки. Тема наследуется от Delta.</p><div class="row"><button data-a="reloadDelta">${ic('arrow-counter-clockwise')} Обновить с сервера</button><button data-a="retryDelta">Повторить сохранение</button><button data-legacy="settings">Часовой пояс</button></div>${Store.conflict||!Store.ok?'<div class="scope-note">Есть несохранённые изменения. Скачайте ZIP перед обновлением с сервера.</div>':''}${Store.lastError?`<p role="alert">Ошибка: ${esc(Store.lastError)}</p>`:''}</section><section class="card"><h3>История активности</h3>${S.log.slice(0,50).map(l=>`<div class="history-row"><span class="m sm">${esc(new Date(l.t).toLocaleString('ru-RU'))}</span><p>${esc(l.x)}</p></div>`).join('')||'<p class="m">Нет событий</p>'}</section></div>`;
